            # If the part contains non-digit characters (e.g., '1a'), stop parsing at that point
            break
    return tuple(parts)<|return|>

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    numbers = []
    num = 0
    in_num = False

    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
            in_num = True
        else:
            if in_num:
                numbers.append(num)
                num = 0
                in_num = False

    if in_num:
        numbers.append(num)

    return tuple(numbers)<|return|>

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    result = []
    for part in parts:
        try:
            num = int(part)
        except ValueError:
            import re
            m = re.match(r'(\d+)', part)
            num = int(m.group(1)) if m else 0
        result.append(num)
    return tuple(result)<|return|>

