    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs
    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return cmd
    import os, sys, shutil, shlex
    program = cmd[0]
    # Handle python scripts with a shebang line
    if os.path.isfile(program) and program.lower().endswith('.py'):
        try:
            with open(program, 'r', encoding='utf-8', errors='ignore') as f:
                first_line = f.readline()
        except Exception:
            first_line = ''
        if first_line.startswith('#!'):
            # Parse the shebang
            shebang = first_line[2:].strip()
            parts = shlex.split(shebang)
            if parts:
                # Resolve 'env' invocation
                if parts[0] == 'env':
                    if len(parts) >= 2:
                        interpreter_name = parts[1]
