        def _make_key(args, kwargs, *, typed=False):
            key = args
            if typed:
                key += tuple(type(v) for v in args)
            kw_items = tuple(sorted(kwargs.items()))
            if typed:
                key += kw_items + tuple(type(v) for _, v in kw_items)
            else:
                key += kw_items
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed=typed)
            now = timer()
            if key in cache:
                result, expire = cache[key]
                if expire > now:
                    cache.move_to_end(key)
                    return result
                # expired
                del cache[key]
            result = func(*args, **kwargs)
            expire = now + ttl
            cache[key] = (result, expire)
            cache.move_to_end(key)
            if maxsize is not None and len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        @contextmanager
        def put(*args, **kwargs):
            key = _make_key(args, kwargs, typed=typed)
            exp = timer() + ttl
            yield lambda value: cache.__setitem__(key, (value, exp))

        wrapper.put = put

        def forget(*args, **kwargs):
            key = _make_key(args, kwargs, typed=typed)
            cache.pop(key, None)

        wrapper.forget = forget

        def clear():
            cache.clear()

        wrapper.clear = clear

        return wrapper

    return decorator<|return|>

