def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        counts = {}
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build the cache key
            kw_items = tuple(sorted(kwargs.items()))
            if typed:
                key = args + tuple(type(v) for v in args) + kw_items + tuple(type(v) for _, v in kw_items)
            else:
                key = args + kw_items

            if key in cache:
                counts[key] += 1
                return cache[key]

            result = func(*args, **kwargs)

            if maxsize and len(cache) >= maxsize:
                # Evict the least frequently used item(s)
                min_count = min(counts.values())
                # Remove the first key encountered with the minimal count
                for evict_key in list(counts.keys()):
                    if counts[evict_key] == min_count:
                        cache.pop(evict_key, None)
                        counts.pop(evict_key, None)
                        break

            cache[key] = result
            counts[key] = counts.get(key, 0) + 1
            return result

        return wrapper
    return decorator<|return|>

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if maxsize is None or maxsize <= 0:
        maxsize = float('inf')

    def decorator(fn):
        if not callable(fn):
            raise TypeError('lfu_cache can only decorate callable objects')

        from functools import wraps

        cache = {}
        freq = {}

        def _make_key(args, kwargs):
            key = args
            if kwargs:
                # Convert kwargs to a tuple of sorted items
                key += ('|',) + tuple(sorted(kwargs.items()))
            if typed:
                # Include argument types in the key to differentiate by type
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(type(v) for k, v in sorted(kwargs.items()))
            return key

        @wraps(fn)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            if key in cache:
                # Update frequency for hit
                freq[key] = freq.get(key, 0) + 1
                return cache[key]

            # Compute result and potentially evict
            result = fn(*args, **kwargs)

            if len(cache) >= maxsize:
                # Find the least frequently used key(s)
                min_f = min(freq.values())
                # Choose a key with the minimum frequency to evict
                for evict_key, f in freq.items():
                    if f == min_f:
                        break
                cache.pop(evict_key, None)
                freq.pop(evict_key, None)

            cache[key] = result
            freq[key] = 1
            return result

        return wrapper

    return decorator<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        return dict.popitem(self, last=False)
