def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return tuple()
    result = []
    for cls in classes:
        # Skip if some other class in the list is a subclass of this one
        if not any(
            other is not cls
            and isinstance(other, type)
            and issubclass(other, cls)
            for other in classes
        ):
            result.append(cls)
    return tuple(result)<|return|>

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Keep only those classes that are not superclasses of any other
    minimal = []
    for cls in classes:
        # Skip if any other class in the list is a subclass of cls
        if any(other is not cls and issubclass(other, cls) for other in classes):
            continue
        minimal.append(cls)
    return minimal<|return|>

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = {}
    cls = self.__class__
    # Collect attributes defined directly on the class
    for name, obj in cls.__dict__.items():
        if name.startswith('_'):
            continue
        desc = None
        if callable(obj):
            desc = obj.__doc__
        elif hasattr(obj, "__doc__"):
            desc = getattr(obj, "__doc__")
        if desc:
            result[name] = desc.strip()
    # Optionally include inherited attributes
    if all:
        for base in cls.__mro__[1:]:
            for name, obj in base.__dict__.items():
                if name.startswith('_') or name in result:
                    continue
                desc = None
                if callable(obj):
                    desc = obj.__doc__
                elif hasattr(obj, "__doc__"):
                    desc = getattr(obj, "__doc__")
                if desc:
                    result[name] = desc.strip()
    return result
<|return|>

