def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Names that are directly set on the instance
    names = list(vars(self).keys())

    # Optionally include names defined on the class (properties, descriptors, etc.)
    if all:
        for cls in self.__class__.__mro__:
            for name, value in vars(cls).items():
                if name.startswith('_'):
                    continue
                if callable(value):
                    continue
                names.append(name)

    # Remove duplicates, exclude built‑in attributes, and return sorted list
    return sorted(set(name for name in names if not name.startswith('_')))<|return|>

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    names = []
    for name in dir(self):
        if not all and name.startswith('_'):
            continue
        # Skip common built-in attributes
        if name in ('__class__', '__dict__', '__weakref__'):
            continue
        try:
            value = getattr(self, name)
        except AttributeError:
            continue
        if callable(value):
            continue
        names.append(name)
    return names<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If the sequence has a base class named 'Broken', treat it as a terminal object
    if Broken in getattr(sequence, "__bases__", ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output<|return|>

