def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    import sys

    out = sys.stdout
    if header is not None:
        out.write(str(header) + "\n")

    for point in self:
        # Try to get coordinates
        try:
            coords = point.coordinates()
        except Exception:
            # Assume point is a tuple/list: first element is coordinates
            try:
                coords = point[0]
            except Exception:
                coords = []

        # Try to get value(s)
        try:
            val = point.value
        except Exception:
            try:
                val = point[1]
            except Exception:
                val = None

        # Build line parts
        line_parts = []
        if isinstance(coords, (tuple, list)):
            line_parts.extend([str(c) for c in coords])
        else:
            line_parts.append(str(coords))

        if isinstance(val, (tuple, list)):
            line_parts.extend([str(v) for v in val])
        else:
            if val is not None:
                line_parts.append(str(val))

        out.write(separator.join(line_parts) + "\n")<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve the coordinate variable by name
    coord = None
    if hasattr(self, "variables") and isinstance(self.variables, dict):
        coord = self.variables.get(coord_name)
    if coord is None:
        return []

    # Attempt to locate the corresponding error variable
    err = None
    # 1. Check if the coordinate object itself has an 'err' attribute
    if hasattr(coord, "err"):
        err = getattr(coord, "err")
    # 2. Fall back to a separate variable named <coord_name>_err
    if err is None:
        err_name = f"{coord_name}_err"
        err = getattr(self, err_name, None)
        if err is None and hasattr(self, "variables"):
            err = self.variables.get(err_name)

    # If no error variable is found, return an empty list
    if err is None:
        return []

    # Convert the error value to a NumPy array if possible
    try:
        err_arr = np.asarray(err)
    except Exception:
        return []

    # Determine indices where error values are finite (i.e., not NaN or inf)
    with np.errstate(invalid="ignore", divide="ignore", over="ignore"):
        mask = np.isfinite(err_arr)
    # Return the indices as a list of integers
    return np.where(mask)[0].tolist()
<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve the error mask for the specified coordinate.  The internal
    # representation may be one of:
    #
    # * a boolean NumPy array or similar (True indicates an error at that
    #   index),
    # * a sequence of indices where errors occur,
    # * a DataArray‑like object exposing a ``.values`` attribute.
    #
    # The method returns a NumPy integer array of indices where the
    # corresponding coordinate is in error.  If the coordinate is not
    # present or no errors are recorded, an empty array is returned.
    #
    if not hasattr(self, "errors") or self.errors is None:
        return np.array([], dtype=int)

    err_obj = self.errors.get(coord_name)
    if err_obj is None:
        return np.array([], dtype=int)

    # Handle list/tuple of indices
    if isinstance(err_obj, (list, tuple)):
        return np.asarray(err_obj, dtype=int)

    # Handle DataArray‑like objects
    if hasattr(err_obj, "values"):
        err_obj = err_obj.values

    try:
        err_arr = np.asarray(err_obj)
    except Exception:  # pragma: no cover
        return np.array([], dtype=int)

    # If arr is boolean mask, return indices where mask is True
    if err_arr.dtype == bool or err_arr.dtype == np.bool_:
        return np.flatnonzero(err_arr)

    # If numeric array, treat non‑zero entries as error indices
    if err_arr.ndim == 1:
        return np.arange(err_arr.size)[err_arr != 0]

    # Fallback if no recognizable pattern
    return np.array([], dtype=int)<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # The mapping from coordinate name to its error indices is expected to
    # be stored in `self._err_indices`.  If it is not present or the
    # coordinate is not known, return an empty integer array.
    indices_dict = getattr(self, "_err_indices", None)
    if not indices_dict or coord_name not in indices_dict:
        return np.array([], dtype=int)
    return np.array(indices_dict[coord_name], dtype=int)<|return|>

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Directly a FillRequest is always usable
    if isinstance(seq, FillRequest):
        return True

    # Don't allow Source sequences to be treated as FillRequestSeq
    if isinstance(seq, Source):
        return False

    # If seq is iterable, check for presence of a FillRequest element
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
