def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    """
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dict")
    if not isinstance(d2, dict):
        return d1  # if d2 is not a dict, everything from d1 is considered different

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # key missing in d2
            result[key] = val1
            continue

        val2 = d2[key]
        # both values are dicts and we are allowed to recurse
        if isinstance(val1, dict) and isinstance(val2, dict) and level != 0:
            # compute recursion depth for next level
            next_level = level - 1 if level > 0 else -1
            sub_diff = difference(val1, val2, next_level)
            if sub_diff:
                result[key] = sub_diff
        else:
            # compare non-dict or recursion disabled
            if val1 != val2:
                result[key] = val1

    return result<|return|>

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1, if a key is present both in *d1* and
    *d2* but has different values, it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError('difference expects two dictionaries')
    def _diff(a, b, depth):
        diff = {}
        for key, val in a.items():
            if key not in b:
                # key only in d1: use value directly (shared reference is fine)
                diff[key] = val
            else:
                val2 = b[key]
                # if both values are dicts and we are allowed to recurse
                if isinstance(val, dict) and isinstance(val2, dict) and depth != 0:
                    sub_depth = depth - 1 if depth > 0 else -1  # -1 means infinite
                    subdiff = _diff(val, val2, sub_depth)
                    if subdiff:
                        diff[key] = subdiff
                elif val != val2:
                    diff[key] = val
        return diff
    return _diff(d1, d2, level)<|return|>

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    import numpy as np

    # Ensure coordinates are in a (N, D) array
    coord_arr = np.atleast_2d(coord).astype(float)

    # Convert edges to a list of 1‑D arrays
    if isinstance(self.edges, (list, tuple)):
        edges_list = [np.asarray(e) for e in self.edges]
    else:
        edges_list = [np.asarray(self.edges)]

    ndim = len(edges_list)
    if coord_arr.shape[1] != ndim:
        raise ValueError(
            f"Coordinate dimensionality {coord_arr.shape[1]} does not match "
            f"histogram dimensions {ndim}."
        )

    # Find bin indices and mask for points inside the histogram bounds
    bin_indices = []
    inside_mask = np.ones(coord_arr.shape[0], dtype=bool)
    for d, edges in enumerate(edges_list):
        idx = np.searchsorted(edges, coord_arr[:, d], side="right") - 1
        mask = (idx >= 0) & (idx < len(edges) - 1)
        inside_mask &= mask
        bin_indices.append(idx)

    # No valid points; nothing to do
    if not np.any(inside_mask):
        return

    # Prepare indices and weights
    if ndim == 1:
        indices = bin_indices[0][inside_mask]
    else:
        indices = np.vstack([b[inside_mask] for b in bin_indices]).T

    # Standardise the weight array
    if hasattr(weight, "__iter__"):
        w_arr = np.asarray(weight)
        if w_arr.ndim == 0:
            w_arr = np.full(indices.shape[0], w_arr)
        elif w_arr.size != indices.shape[0]:
            w_arr = np.full(indices.shape[0], w_arr.flat[0])
    else:
        w_arr = np.full(indices.shape[0], weight)

    # Accumulate into the histogram
    if ndim == 1:
        np.add.at(self.hist, indices, w_arr)
    else:
        flat_indices = np.ravel_multi_index(indices.T, self.hist.shape)
        np.add.at(self.hist.flat, flat_indices, w_arr)<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    key_regex = re.compile(r"^[_a-zA-Z][_a-zA-Z0-9]*$")
    val_regex = re.compile(r"^[\w ]+$")

    errors = []

    for key, val in labels.items():
        # Validate the key itself
        if not isinstance(key, (str, bytes, bytearray)):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            if not key_regex.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex [{key_regex.pattern}]"}
                )

        # Validate the value(s)
        if isinstance(val, (list, tuple)):
            for item in val:
                if not isinstance(item, (str, bytes, bytearray)):
                    errors.append({repr(val): "expected string or bytes-like object"})
                else:
                    if not val_regex.match(item):
                        errors.append(
                            {repr(val): f"Label value '{item}' does not match the regex "
                                         f"[{val_regex.pattern}]"}
                        )
        else:
            if not isinstance(val, (str, bytes, bytearray)):
                errors.append({repr(val): "expected string or bytes-like object"})
            else:
                if not val_regex.match(val):
                    errors.append(
                        {repr(val): f"Label value '{val}' does not match the regex "
                                     f"[{val_regex.pattern}]"}
                    )

    if errors:
        raise ValidationError(errors)<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []
    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): 'expected string or bytes-like object'})
        else:
            if not getattr(_validate_labels, 'LABEL_KEY_REGEX', None) or not getattr(_validate_labels, 'LABEL_KEY_REGEX').match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})
        # Validate value(s)
        def _add_value_error(val):
            if not isinstance(val, (str, bytes)):
                errors.append({repr(val): 'expected string or bytes-like object'})
            else:
                if not getattr(_validate_labels, 'LABEL_VALUE_REGEX', None) or not getattr(_validate_labels, 'LABEL_VALUE_REGEX').match(val):
                    errors.append({val: f"Label value '{val}' does not match the regex [...]"})

        if isinstance(value, (list, tuple, set)):
            for item in value:
                _add_value_error(item)
        else:
            _add_value_error(value)

    if errors:
        raise ValidationError(errors)<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
