def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    for field, subschema in observer_schema.items():
        # Initialize value if missing
        if field not in last_applied_manifest:
            if field not in response:
                raise KeyError(
                    "Observed field %r missing in response" % field
                )
            last_applied_manifest[field] = response[field]

        # Recurse into nested dicts
        if isinstance(subschema, dict):
            # Ensure the nested dictionary exists and is dict
            if not isinstance(last_applied_manifest[field], dict):
                last_applied_manifest[field] = {}
            if field not in response or not isinstance(response[field], dict):
                raise KeyError(
                    "Expected dict for field %r in response" % field
                )
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field],
                subschema,
                response[field]
            )
    return last_applied_manifest<|return|>

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, schema in observer_schema.items():
        # Skip list handling; lists are managed by update_last_applied_manifest_list_from_resp
        if isinstance(schema, list):
            continue

        # If the schema indicates a nested dictionary, recurse
        if isinstance(schema, dict):
            # Ensure the nested dict exists in the manifest
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            # Get the corresponding part of the response
            sub_resp = response.get(key)
            if sub_resp is None:
                raise KeyError(f"Missing key '{key}' in response while processing nested dict")
            # Recursively update the nested dict
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema, sub_resp
            )
        else:
            # Leaf field; initialise only if absent
            if key not in last_applied_manifest:
                if key not in response:
                    raise KeyError(f"Missing key '{key}' in response while processing dict field")
                last_applied_manifest[key] = response[key]
    return last_applied_manifest<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # If the application has no spec or manifest, nothing to do
    spec = getattr(app, "spec", None)
    if spec is None:
        return

    # Ensure observers dict exists on the spec
    observers = getattr(spec, "observers", None)
    if observers is None:
        observers = {}
        setattr(spec, "observers", observers)

    # Get the manifest resources; it might be a list or a dict
    manifests = getattr(spec, "manifest", None)
    if manifests is None:
        return

    if isinstance(manifests, dict):
        resources = manifests.values()
    else:
        resources = manifests

    # For each resource in the manifest, ensure a default observer schema is present
    for resource in resources:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        if kind not in observers:
            # Use a minimal schema containing only apiVersion and kind
            observers[kind] = {
                "apiVersion": resource.get("apiVersion"),
                "kind": kind,
            }<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the observer_schemas dict exists on the spec
    if not hasattr(app.spec, 'observer_schemas') or app.spec.observer_schemas is None:
        app.spec.observer_schemas = {}
    # Iterate over each resource in the manifest
    for resource in getattr(app.spec, 'manifest', []):
        kind = resource.get('kind')
        metadata = resource.get('metadata', {})
        name = metadata.get('name')
        namespace = metadata.get('namespace', 'default')
        if not all([kind, name]):
            # Skip resources that do not have the expected fields
            continue
        resource_id = f"{kind}:{namespace}/{name}"
        # Skip if a custom observer schema is already defined
        if resource_id in app.spec.observer_schemas:
            continue
        # Create a default empty observer schema for this resource
        app.spec.observer_schemas[resource_id] = {}
    return app.spec.observer_schemas<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the observer_schema attribute exists
    if not hasattr(app.spec, 'observer_schema') or app.spec.observer_schema is None:
        app.spec.observer_schema = {}

    # Iterate through resources defined in the manifest
    for resource_name, resource_spec in app.spec.manifest.items():
        # Skip if a custom observer schema already exists for this resource
        if resource_name in app.spec.observer_schema:
            continue

        # Build a simple default observer schema: we observe all top‑level keys
        # of the resource definition by creating an `object` type schema
        default_schema = {'type': 'object', 'properties': {}}
        if isinstance(resource_spec, dict):
            for key, value in resource_spec.items():
                if isinstance(value, dict):
                    default_schema['properties'][key] = {'type': 'object'}
                elif isinstance(value, list):
                    default_schema['properties'][key] = {'type': 'array'}
                else:
                    default_schema['properties'][key] = {'type': type(value).__name__}
        else:
            # If the resource spec is not a dict, type it as string
            default_schema['properties'] = {}

        app.spec.observer_schema[resource_name] = default_schema<|return|>

