        return "?"

    # Determine whether we are dealing with named or positional parameters
    if isinstance(params, Mapping):
        # Named parameters: expect syntax like :name
        placeholder_pattern = re.compile(r":(\w+)")
        names = placeholder_pattern.findall(sql_str)
        if not names:
