            if pname not in params:
                raise KeyError(f"Parameter '{pname}' not provided in params mapping")
            ordered_params.append(params[pname])
            if self.out_style == "?":
                return "?"
            if self.out_style.startswith("$"):
                return numbered_placeholder(len(ordered_params))
            if "%" in self.out_style:
                # assume Python %s style
                return self.out_style % ()
            # Fallback: keep the same placeholder
            return match.group(0)

        out_sql = placeholder_pattern.sub(repl, sql_str)

        # Convert back to bytes if original SQL was bytes
