                    try:
                        spec_version = float(f"{parts[0]}.{parts[1]}")
                    except ValueError:
                        # Fall back to the default if parsing fails
                        spec_version = self.spec_version

        # Basic required keys irrespective of spec_version
        required_keys = ['name', 'type']
        for key in required_keys:
            if key not in inventory:
                raise ArgumentError(key, f"Missing required key '{key}' in inventory")

        # Additional checks depending on the resolved specification version
        if spec_version == 1.0:
            # Version 1.0 expects an 'attributes' dict
            if 'attributes' not in inventory or not isinstance(inventory['attributes'], dict):
                raise ArgumentError('attributes', "Version 1.0 inventory must include an 'attributes' dictionary")
        elif spec_version == 2.0:
            # Version 2.0 expects a 'metadata' dict
            if 'metadata' not in inventory or not isinstance(inventory['metadata'], dict):
                raise ArgumentError('metadata', "Version 2.0 inventory must include a 'metadata' dictionary")
