def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Gather all digests listed in the manifest files
    manifest_digests = set()
    for mf in manifest_files:
        try:
            with open(mf, 'r', encoding='utf-8') as fh:
                for line in fh:
                    d = line.strip()
                    if d:
                        manifest_digests.add(d)
        except FileNotFoundError:
            raise FileNotFoundError(f"Manifest file {mf} does not exist.")

    # Digests that are used but not listed in any manifest
    used_not_in_manifest = set(digests_used) - manifest_digests
    if used_not_in_manifest:
        raise ValueError(
            f"Digests used but not listed in manifests: "
            f"{', '.join(sorted(used_not_in_manifest))}"
        )

    # Digests that are listed in a manifest but not used anywhere
    manifest_not_used = manifest_digests - set(digests_used)
    if manifest_not_used:
        raise ValueError(
            f"Digests listed in manifests but not used: "
            f"{', '.join(sorted(manifest_not_used))}"
        )

    return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # manifest_files is expected to be a mapping of filename to digest string.
    # digests_used is a set or collection of digests that have been used.
    missing_files = []
    for filename, digest in manifest_files.items():
        if digest not in digests_used:
            missing_files.append(filename)

    if missing_files:
        raise ValueError(
            f"The following files have digests that were listed in the manifest "
            f"but were not used: {', '.join(missing_files)}"
        )
    # If no problems, return True for convenience.
    return True<|return|>

