                raise ValueError(err_msg.format(
                    'Propensities matrix size mismatch between current and prior instances'
                ))

        # Ensure all current species exist in prior
        if hasattr(self, 'species') and hasattr(prior, 'species'):
            missing_species = set(self.species) - set(prior.species)
            if missing_species:
                raise ValueError(
                    err_msg.format(f'Missing species in prior inventory: {missing_species}')
                )

        # Ensure all current parameters exist in prior
        if hasattr(self, 'parameters') and hasattr(prior, 'parameters'):
            missing_params = set(self.parameters) - set(prior.parameters)
            if missing_params:
                raise ValueError(
                    err_msg.format(f'Missing parameters in prior inventory: {missing_params}')
                )

        # If all checks pass, return True
        return True<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Normalize the target version
    if version in (None, "latest"):
        try:
            target_version = max(inventory.keys())
        except Exception:
            raise ValueError("Inventory is empty or contains non-string keys")
    else:
        target_version = version

    logical_map = {}
    for ver, data in inventory.items():
        # Skip older versions
        try:
            if ver < target_version:
                continue
        except Exception:
            # If version objects are not comparable, skip comparison
            pass

        # Determine the iterable of pairs (logical_path, content_file)
        if isinstance(data, dict):
            items = data.items()
        elif isinstance(data, (list, set, tuple)):
            items = data
        else:
            # Unsupported data format for this version entry
            continue

        for logical_path, content_file in items:
            logical_map.setdefault(logical_path, set()).add(content_file)

    return logical_map<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to compare two simple version strings that follow numeric
    # dotted notation (e.g. "1.2.3"). If the format does not match, fall
    # back to lexical comparison.
    def _version_le(v1, v2):
        try:
            parts1 = [int(p) for p in v1.split('.')]
            parts2 = [int(p) for p in v2.split('.')]
            return parts1 <= parts2
        except Exception:
            return v1 <= v2

    path_map = {}
    for logical_path, content in inventory.items():
        files = set()
        # Inventories can be either a mapping of version->file path
        # or a simple iterable of file paths.
        if isinstance(content, dict):
            for ver, fname in content.items():
                if _version_le(ver, version):
                    files.add(fname)
                # also include duplicate references from later versions
                # if later versions reference the same file, we still add it
                elif _version_le(version, ver):
                    # check if this file is already present in files
                    if fname in files:
                        continue
        elif hasattr(content, '__iter__') and not isinstance(content, str):
            for fname in content:
                files.add(fname)
        else:
            # If content is a single file path, add it directly
            files.add(content)
        if files:
            path_map[logical_path] = files
    return path_map<|return|>

def get_logical_path_map(inventory, version):
