    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")
    # Retrieve the mapping for the requested version; return empty dict if not found
    version_map = inventory.get(version)
    if version_map is None:
        return {}
    if not isinstance(version_map, dict):
        raise TypeError(
            f"inventory[version] must be a dict of logical_path -> content files, "
            f"got {type(version_map).__name__}"
        )
    logical_map = {}
    for logical_path, content_files in version_map.items():
        # Normalise to a set; assume content_files is iterable
        if isinstance(content_files, set):
            content_set = content_files
        else:
            content_set = set(content_files)
        logical_map[logical_path] = content_set
    return logical_map<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}
    for record in inventory:
        rec_version = record.get('version')
        if rec_version is None:
            continue
        # Include files from the requested version and any later versions.
        if rec_version == version or rec_version > version:
            logical_path = record.get('logical_path')
            content_file = record.get('content_file')
            if logical_path is None or content_file is None:
                continue
            path_map.setdefault(logical_path, set()).add(content_file)
    return path_map<|return|>

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")

        required_keys = {"file", "checksum"}
        optional_keys = {"policy", "size", "type"}
        keys = set(fixity.keys())

        missing = required_keys - keys
        if missing:
            raise ValueError(f"Fixity block missing required keys: {missing}")

        unknown = keys - required_keys - optional_keys
        if unknown:
            raise ValueError(f"Fixity block contains unknown keys: {unknown}")

        # Validate file reference
        file_ref = fixity["file"]
        if file_ref not in manifest_files:
            raise ValueError(f"Fixity block references unknown file: {file_ref}")

        # Validate checksum structure
        checksum = fixity["checksum"]
        if not isinstance(checksum, dict):
            raise ValueError("Checksum must be a dictionary")
        if "algorithm" not in checksum or "value" not in checksum:
            raise ValueError("Checksum dictionary must contain 'algorithm' and 'value'")
        if not isinstance(checksum["algorithm"], str):
            raise ValueError("Checksum algorithm must be a string")
        if not isinstance(checksum["value"], str):
            raise ValueError("Checksum value must be a string")

        # Optional fields
        if "policy" in fixity and not isinstance(fixity["policy"], str):
            raise ValueError("Policy must be a string")
        if "size" in fixity and not isinstance(fixity["size"], int):
            raise ValueError("Size must be an integer")

        return True<|return|>

