def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary mapping filenames to hash dicts")

    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("Manifest files must be an iterable of file paths")

    # Normalize manifest to a set for efficient lookup
    manifest_set = set(manifest_files)

    # Allowed hash algorithms and their expected digest lengths
    hash_lengths = {
        'md5': 32,
        'sha1': 40,
        'sha256': 64,
        'sha512': 128,
    }

    for file_path, checksums in fixity.items():
        # Ensure the file is present in the manifest
        if file_path not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{file_path}' not in manifest")

        if not isinstance(checksums, dict):
            raise ValueError(f"Checksum entry for '{file_path}' must be a dictionary")

        if not checksums:
            raise ValueError(f"No checksums provided for '{file_path}'")

        for algo, digest in checksums.items():
            # Validate algorithm name
            algo_lower = algo.lower()
            if algo_lower not in hash_lengths:
                raise ValueError(
                    f"Unsupported checksum algorithm '{algo}' for file '{file_path}'. "
                    f"Supported algorithms: {', '.join(hash_lengths.keys())}"
                )

            expected_len = hash_lengths[algo_lower]
            if not isinstance(digest, str):
                raise ValueError(
                    f"Checksum for algorithm '{algo}' of file '{file_path}' must be a string"
                )
            if len(digest) != expected_len:
                raise ValueError(
                    f"Checksum length for algorithm '{algo}' of file '{file_path}' "
                    f"must be {expected_len} characters (got {len(digest)})"
                )
            # Verify all characters are hexadecimal
            if not all(c in "0123456789abcdefABCDEF" for c in digest):
                raise ValueError(
                    f"Checksum for algorithm '{algo}' of file '{file_path}' "
                    f"contains non-hexadecimal characters"
                )
    # No return value needed; validation passes if no exception is raised
    return True<|return|>

