def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping of package basename (from its XML file) to a dict of filename → file content.
    """
    # Collect all file names in the folder
    try:
        all_files = os.listdir(folder)
    except FileNotFoundError:
        return {}

    # Group files by the basename of their XML file (if one exists)
    pkg_files = {}
    xml_basenames = set()

    for name in all_files:
        if name.lower().endswith('.xml'):
            base = os.path.splitext(name)[0]
            xml_basenames.add(base)

    for name in all_files:
        base = os.path.splitext(name)[0]
        if base in xml_basenames:
            pkg_files.setdefault(base, []).append(name)

    # Read the contents of each file in the package groups
    result = {}
    for base, files in pkg_files.items():
        pkg_dict = {}
        for fn in files:
            path = os.path.join(folder, fn)
            try:
                with open(path, 'r', encoding='utf-8', errors='ignore') as fh:
                    pkg_dict[fn] = fh.read()
            except OSError:
                pkg_dict[fn] = None
        result[base] = pkg_dict

    return result
