def add_rendition(self, lang, file_path):
    """
    Adds a rendition for a given language to the file mapping.

    Example mapping:
      {
          "original": "artigo02.pdf",
          "en": "artigo02-en.pdf",
      }
    """
    # Ensure the internal renditions dict exists
    if not hasattr(self, "renditions"):
        self.renditions = {}

    # Determine the original file name
    stem, ext = os.path.splitext(file_path)
    if "-" in stem:
        # Split only on the last dash; the part after the dash is assumed to be the language code
        base_stem, candidate_lang = stem.rsplit("-", 1)
        if len(candidate_lang) == 2 and candidate_lang.isalpha():
            original = f"{base_stem}{ext}"
        else:
            original = f"{stem}{ext}"
    else:
        original = f"{stem}{ext}"

    # Add or update the mapping for the original file
    if original not in self.renditions:
        self.renditions[original] = {}
    self.renditions[original][lang] = file_path

    # Return the updated rendition dictionary for the original file
    return self.renditions[original]<|return|>

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Determine the directory of the source file and ensure it's a file.
    if not os.path.isfile(file_path):
        raise AssetNotFoundError(u("Cannot find source file: {0}").format(file_path))

    source_dir = os.path.dirname(file_path)
    # List of extensions we want to look for beside the one provided.
    extensions = ('.tiff', '.jpg', '.png')
    # Ensure we handle case where the passed file has a different extension
    # by always trying all expected extensions.
    asset_map = {}

    # Ensure the destination asset directory exists
    if not os.path.isdir(self._asset_path):
        os.makedirs(self._asset_path, exist_ok=True)

    for ext in extensions:
        src = os.path.join(source_dir, basename + ext)
        if os.path.isfile(src):
            dest = os.path.join(self._asset_path, basename + ext)
            shutil.copyfile(src, dest)
            asset_map[basename + ext] = dest

    # If nothing was copied, raise an error.
    if not asset_map:
        raise AssetNotFoundError(
            u("No assets found for base name '{0}' in '{1}'").format(basename, source_dir)
        )

    return asset_map<|return|>

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Determine the directory that contains the file and confirm the basename
    directory, filename = os.path.split(file_path)
    base, ext = os.path.splitext(filename)
    if base != basename:
        raise ValueError(f"Provided basename '{basename}' does not match file base '{base}'.")

    # List of extensions we care about
    extensions = [".tiff", ".jpg", ".png"]

    # Build a mapping from each found filename to its full path
    asset_map = {}
    for extension in extensions:
        candidate = os.path.join(directory, basename + extension)
        if os.path.exists(candidate):
            asset_map[basename + extension] = candidate

    return asset_map<|return|>

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML basename to a dict of contained file names and their contents.
    """
    data = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                name = zinfo.filename
                # Skip directories
                if name.endswith('/'):
                    continue
                # Determine the XML basename from any .xml file
                if name.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(name))[0]
                    content = zin.read(name)
                    # Try to decode as UTF-8, fallback to binary
                    try:
                        content = content.decode('utf-8')
                    except UnicodeDecodeError:
                        content = content
                    if base not in data:
                        data[base] = {}
                    data[base][name] = content
    except (FileNotFoundError, zipfile.BadZipFile) as e:
        # Handle missing file or invalid zip gracefully
        logger.warning(f"Could not read zip file {zip_path}: {e}")
    return data<|return|>

