def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    cls_name = self.__class__.__name__
    attrs = {}
    try:
        attrs.update(vars(self))
    except TypeError:
        # object may use __slots__
        for name in getattr(self, '__slots__', ()):
            attrs[name] = getattr(self, name)
    if not attrs:
        return f'{indent_str}{cls_name}()'
    lines = [f'{indent_str}{cls_name}(']
    last_key = None
    for key, value in attrs.items():
        last_key = key
        if hasattr(value, 'pretty') and callable(value.pretty):
            val_str = value.pretty(indent=indent + 4, debug=debug)
        else:
            val_str = repr(value)
        if debug:
            val_str += f' ({type(value).__name__})'
        lines.append(f'{indent_str}    {key}={val_str},')
    # Remove trailing comma from last line
    if last_key is not None:
        lines[-1] = lines[-1].rstrip(',')
    lines.append(f'{indent_str})')
    return '\n'.join(lines)<|return|>

