    indent_str = ' ' * indent
    lines = [f"{indent_str}{self.__class__.__name__}("]
    try:
        attrs = vars(self)
    except TypeError:
        attrs = {}
    for key in sorted(attrs):
        value = attrs[key]
        if hasattr(value, "pretty") and callable(getattr(value, "pretty")):
            val_str = value.pretty(indent=indent + 2)
        else:
            val_str = repr(value)
        lines.append(f"{' ' * (indent + 2)}{key}={val_str},")
    if debug:
        lines.append(f"{' ' * (indent + 2)}_debug_=True,")
    lines.append(f"{indent_str})")
    return '\n'.join(lines)<|return|>

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _repr(obj, level):
        indent_str = '  ' * level
        if isinstance(obj, (str, int, float, bool, type(None))):
            return f"{indent_str}{repr(obj)}"
        if isinstance(obj, dict):
            lines = [f"{indent_str}{{"]
            for k, v in obj.items():
                lines.append(f"{indent_str}  {repr(k)}: {_repr(v, level + 1)}")
            lines.append(f"{indent_str}}}")
            return '\n'.join(lines)
        if isinstance(obj, (list, tuple, set)):
            start = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
            end = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
            lines = [f"{indent_str}{start}"]
            for item in obj:
                lines.append(_repr(item, level + 1))
            lines.append(f"{indent_str}{end}")
            return '\n'.join(lines)
        if hasattr(obj, "__dict__"):
            lines = [f"{indent_str}{obj.__class__.__name__}("]
            for attr, val in obj.__dict__.items():
                lines.append(f"{indent_str}  {attr}={_repr(val, level + 1)}")
            lines.append(f"{indent_str})")
            return '\n'.join(lines)
        return f"{indent_str}{repr(obj)}"

    return _repr(self, indent) if not debug else \
        f"pretty(indent={indent}, debug={debug})\n{_repr(self, indent)}"<|return|>

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    try:
        import json
    except ImportError:
        return repr(self)

    def _dump(value, current_indent):
        if isinstance(value, (list, tuple)):
            return [ _dump(v, current_indent + indent) for v in value ]
        if isinstance(value, dict):
            return {k: _dump(v, current_indent + indent) for k, v in value.items()}
        return value

    obj_rep = getattr(self, '__dict__', None)
    if obj_rep is None:
        output = repr(self)
    else:
        formatted = _dump(obj_rep, 0)
        if indent:
            output = json.dumps(formatted, indent=indent, sort_keys=True, default=str)
        else:
            output = json.dumps(formatted, separators=(',', ': '), default=str)

    if debug:
        cls_name = type(self).__name__
        output = f"{cls_name} {output}"
    return output<|return|>

