def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to read the version from a local version.py file
    try:
        import os
        base = os.path.abspath(os.path.dirname(__file__))
        version_path = os.path.join(base, "version.py")
        with open(version_path, "r") as fp:
            for line in fp:
                if line.lstrip().startswith("__version__"):
                    _, value = line.split("=", 1)
                    return value.strip().strip("'\"")
    except Exception:
        pass

    # Try to get the distribution version using importlib.metadata (Python >=3.8)
    try:
        try:
            import importlib.metadata as importlib_metadata
        except Exception:
            import importlib_metadata
        version = importlib_metadata.version(__package__ or __name__.split(".")[0])
        if version:
            return version
    except Exception:
        pass

    # Fallback default
    return "unknown"<|return|>

