    """Render the given version pieces into the requested style."""
    def _fmt(v):
        return str(v) if v not in (None, '', []) else None

    major = _fmt(pieces.get('major'))
    minor = _fmt(pieces.get('minor'))
    patch = _fmt(pieces.get('patch'))
    pre_release = _fmt(pieces.get('pre_release'))
    build = _fmt(pieces.get('build'))

    if style == 'semver':
        base = '.'.join(filter(None, [major, minor, patch]))
        suffix = ''
        if pre_release:
            suffix += '-' + pre_release
        if build:
            suffix += '+' + build
        return base + suffix

    if style == 'full':
        return '.'.join(filter(None, [major, minor, patch]))

    if style == 'short':
        return '.'.join(filter(None, [major, minor]))

    if style == 'pre':
        return pre_release or ''

    raise ValueError(f"Unsupported style: {style}")<|return|>

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Normalize the pieces list
    pieces = [int(p) if isinstance(p, str) and p.isdigit() else p for p in pieces]

    if style == 'semver':
        # e.g., [1, 0, 3] -> '1.0.3'
        return '.'.join(map(str, pieces))

    if style == 'short':
        # e.g., [1, 0, 3] -> 'v1.0'
        if not pieces:
            return ''
        base = f"v{pieces[0]}"
        if len(pieces) > 1:
            base += f".{pieces[1]}"
        return base

    if style == 'numeric':
        # return a tuple of integers
        return tuple(int(p) for p in pieces)

    if style == 'json':
        # Represent the version as a JSON‑like dict
        keys = ['major', 'minor', 'patch', 'extra']
        formatted = {}
        for i, key in enumerate(keys):
            formatted[key] = pieces[i] if i < len(pieces) else None
        return formatted

    raise ValueError(f"Unsupported style: {style}")<|return|>

