def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Convert the command to a list of strings
    if isinstance(commands, (list, tuple)):
        command_list = list(commands)
    elif isinstance(commands, str):
        command_list = commands.split()
    else:
        raise TypeError('commands must be a string or a list/tuple of arguments')

    # Append any additional arguments
    if args:
        command_list.extend(args)

    if verbose:
        print('Running command:', ' '.join(command_list))

    # Handle standard error redirection
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    # Prepare the environment
    exec_env = os.environ.copy()
    if env:
        exec_env.update(env)

    try:
        output = subprocess.check_output(
            command_list,
            cwd=cwd,
            env=exec_env,
            stderr=stderr_target
        )
    except subprocess.CalledProcessError as exc:
        error_msg = f"Command '{' '.join(command_list)}' failed with exit code {exc.returncode}"
        raise ProgramError(error_msg) from exc

    # Decode output to a string, replacing any problematic bytes
    return output.decode('utf-8', errors='replace')<|return|>

