def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Helper to compute a simple digest for a node
    def _compute_digest(node):
        import hashlib
        m = hashlib.sha256()
        m.update(repr(node).encode("utf-8"))
        return m.hexdigest()

    # Recursive traversal of the hierarchy
    def _visit(node, path="root"):
        nonlocal num_objects, good_objects
        num_objects += 1
        valid = True

        # Validate the node itself
        if validate_objects:
            if hasattr(node, "validate") and callable(node.validate):
                try:
                    node.validate()
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Warning: Validation failed for {path}: {e}")
            elif hasattr(node, "is_valid"):
                try:
                    valid = bool(node.is_valid())
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Warning: Validation check failed for {path}: {e}")

        # Check digest if required
        if check_digests and valid:
            if hasattr(node, "get_digest") and callable(node.get_digest):
                try:
                    expected = node.get_digest()
                    actual = _compute_digest(node)
                    if expected != actual:
                        valid = False
                        if show_warnings:
                            print(f"Warning: Digest mismatch for {path}: expected {expected}, got {actual}")
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Warning: Digest check failed for {path}: {e}")

        if valid:
            good_objects += 1

        # Recurse into children if present
        if hasattr(node, "children") and isinstance(node.children, (list, tuple)):
            for idx, child in enumerate(list(node.children)):
                _visit(child, f"{path}/{idx}")
        elif hasattr(node, "children") and isinstance(node.children, dict):
            for key, child in node.children.items():
                _visit(child, f"{path}/{key}")

    # Start traversal from the storage root
    if not hasattr(self, "storage_root"):
        raise AttributeError("self does not have a 'storage_root' attribute to validate")
    _visit(self.storage_root)
    return num_objects, good_objects<|return|>

