def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ''
    parts = version.split('.')
    try:
        last = parts[-1]
        width = len(last)
        new_last = str(int(last) + 1).zfill(width)
        return '.'.join(parts[:-1] + [new_last])
    except ValueError:
        # In case non-numeric components are present, simply append '.1'
        return f"{version}.1"<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    # Ensure root inventory is available for comparison
    if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
        raise ValueError("Root inventory not available for comparison in validate_version_inventories")

    # Record of any digest differences between each version inventory and the root
    self.different_digests = {}

    for ver_dir in version_dirs:
        inv_path = os.path.join(ver_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file in version directory {ver_dir!r}")

        with open(inv_path, "r", encoding="utf-8") as f:
            try:
                inv = json.load(f)
            except Exception as exc:
                raise ValueError(f"Invalid JSON inventory in {ver_dir!r}: {exc}") from exc

        # Each inventory must contain at least all entries from the root inventory
        missing_entries = set(self.root_inventory) - set(inv)
        if missing_entries:
            raise ValueError(f"Inventory in {ver_dir!r} missing entries: {sorted(missing_entries)!r}")

        # Capture any digest differences for this version
        diffs = {}
        for path, root_digest in self.root_inventory.items():
            version_digest = inv.get(path)
            if version_digest is None:
                # The earlier check guarantees this path exists, but guard just in case
                continue
            if root_digest != version_digest:
                diffs[path] = {"root": root_digest, "version": version_digest}

        if diffs:
            self.different_digests[ver_dir] = diffs

    return self<|return|>

