        cumulative_keys.update(inv.keys())
        missing = cumulative_keys - inv.keys()
        if missing:
            raise ValueError(f'Inventory {inv_path} missing entries expected from earlier versions: {missing}')

        # record any digest differences from the root inventory
        for path, digest in inv.items():
            root_digest = self.root_inventory.get(path)
            if root_digest is not None and root_digest != digest:
                self.differing_digests[path] = (root_digest, digest)

    return self<|return|>

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not hasattr(self, "_root_inventory"):
        raise RuntimeError("root inventory must be loaded before validation")
    root_inventory = self._root_inventory

    divergent = {}

    for ver in version_dirs:
        inv_path = Path(ver) / "inventory.json"
        if not inv_path.is_file():
            raise FileNotFoundError(f"Missing inventory for version '{ver}': {inv_path}")

        with open(inv_path) as fp:
            try:
                version_inventory = json.load(fp)
            except ValueError as exc:
                raise ValueError(f"Invalid JSON in inventory '{inv_path}': {exc}") from exc

        for key, digest in version_inventory.items():
            if key not in root_inventory:
                raise ValueError(f"Key {key!r} in inventory of version '{ver}' "
                                 f"is not present in the root inventory")
            root_digest = root_inventory[key]
            if digest != root_digest:
                divergent.setdefault(key, []).append((ver, digest))

    # Store divergent digests for later checks
    self._divergent_digests = divergent
    return self
