def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Helper: check if a name matches the Namaste pattern
    def _is_namaste(name):
        return isinstance(name, str) and name.startswith("0=")

    if not os.path.exists(path):
        return f"Path does not exist: {path}"

    # If it's a file, check whether it is a Namaste file
    if os.path.isfile(path):
        base = os.path.basename(path)
        if _is_namaste(base):
            return "file"
        else:
            return f"File is not a Namaste file: {base}"

    # It's a directory – examine its contents
    try:
        entries = os.listdir(path)
    except OSError as exc:
        return f"Cannot access directory: {exc}"

    namaste_entries = [e for e in entries if _is_namaste(e)]
    if not namaste_entries:
        return "No Namaste files found – cannot determine type"

    # If the directory contains a subdirectory named "objects" or any
    # subdirectory that itself contains a Namaste file, we consider it a root
    has_objects_dir = "objects" in entries and os.path.isdir(os.path.join(path, "objects"))
    for sub in entries:
        full = os.path.join(path, sub)
        if os.path.isdir(full):
            try:
                sub_entries = os.listdir(full)
                if any(_is_namaste(e) for e in sub_entries):
                    has_objects_dir = True
                    break
            except OSError:
                continue

    if has_objects_dir:
        return "root"

    # Otherwise, the presence of Namaste files in this directory suggests
    # it is an OCFL object directory.
    return "object"<|return|>

