def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two distinct symbols.")
    digit_map = {symbol: i for i, symbol in enumerate(alphabet)}
    value = 0
    for char in string:
        if char not in digit_map:
            raise ValueError(f"Character '{char}' not found in alphabet.")
        value = value * base + digit_map[char]
    return value<|return|>

def string_to_int(string: str, alphabet: list) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two symbols.")
    value_map = {ch: i for i, ch in enumerate(alphabet)}
    num = 0
    for ch in string:
        if ch not in value_map:
            raise ValueError(f"Character '{ch}' not found in alphabet.")
        num = num * base + value_map[ch]
    return num<|return|>

