def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # POSIX-like split using REGEX
    def _posix_split(text):
        pattern = re.compile(r'''(?:"([^"]*)"|'([^']*)'|([^ \t\r\n\v\f]+))''')
        tokens = []
        for part in pattern.findall(text):
            token = part[0] if part[0] else (part[1] if part[1] else part[2])
            tokens.append(token)
        return tokens

    # Windows CMD-style split using REGEX
    def _windows_split(text):
        # matches either a quoted string with escaped quotes or a non-space token
        pattern = re.compile(r'''(?:"((?:[^"\\]|\\.)*)"|([^ \t\r\n\v\f]+))''')
        tokens = []
        for match in pattern.finditer(text):
            if match.group(1) is not None:
                token = match.group(1)
                # Handle backslash escapes inside quotes
                token = token.replace(r'\"', '"').replace(r'\\', '\\')
            else:
                token = match.group(2)
            tokens.append(token)
        return tokens

    # Determine platform mode
    if platform == 'this':
        # Default to POSIX on this platform
        # Since we cannot detect OS without imports, fall back to POSIX behavior.
        return _posix_split(s)
    if platform in (1, 'posix'):
        return _posix_split(s)
    if platform in (0, 'windows', 'cmd'):
        return _windows_split(s)

    raise ValueError('Unsupported platform: %r' % platform)<|return|>

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command‑line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1

    if platform == 1:
        import shlex
        return shlex.split(s)

    # Windows/CMD style splitting
    # Matches: double‑quoted strings, single‑quoted strings, or unquoted words
    pattern = re.compile(r'''
        "([^"\\]*(?:\\.[^"\\]*)*)"   |   # double‑quoted
        '([^'\\]*(?:\\.[^'\\]*)*)'   |   # single‑quoted
        ([^\s"']+)                            # unquoted
    ''', re.VERBOSE)

    def _unescape(escaped):
        """Remove backslash escapes."""
        return re.sub(r'\\(.)', r'\1', escaped)

    parts = []
    for m in pattern.finditer(s):
        if m.group(1) is not None:
            part = _unescape(m.group(1))
        elif m.group(2) is not None:
            part = _unescape(m.group(2))
        else:
            part = m.group(3)
        parts.append(part)
    return parts<|return|>

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    cmd = ['git', 'ls-files', '--others', '--ignored', '--exclude-standard']
    try:
        output = subprocess.check_output(
            cmd, cwd=ignored, stderr=subprocess.STDOUT, text=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.output}") from e
    files = sorted(filter(None, output.splitlines()))
    return ','.join(files)<|return|>

