def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == 'always':
        return None
    if not isinstance(frequency, str):
        raise ValueError('Frequency must be a string')
    parts = frequency.strip().split()
    if len(parts) != 2:
        raise ValueError(f'Invalid frequency format: {frequency!r}')
    number_str, unit = parts
    try:
        value = int(number_str)
    except ValueError:
        raise ValueError(f'Invalid number in frequency: {number_str!r}')
    unit = unit.lower()
    kwargs = {}
    if unit in ('day', 'days'):
        kwargs['days'] = value
    elif unit in ('hour', 'hours', 'h'):
        kwargs['hours'] = value
    elif unit in ('minute', 'minutes', 'm'):
        kwargs['minutes'] = value
    elif unit in ('second', 'seconds', 's'):
        kwargs['seconds'] = value
    elif unit in ('week', 'weeks', 'w'):
        kwargs['weeks'] = value
    else:
        raise ValueError(f'Unsupported unit in frequency: {unit!r}')
    return datetime.timedelta(**kwargs)<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or str(frequency).strip().lower() == "always":
        return None

    freq_str = str(frequency).strip()
    import re
    match = re.fullmatch(r'\s*(\d+(?:\.\d+)?)\s*([a-zA-Z]+)\s*', freq_str)
    if not match:
        raise ValueError(f"Unable to parse frequency: {frequency}")

    number_str, unit = match.group(1), match.group(2).lower()
    try:
        # allow floats but cast to integer for timedelta arguments
        value = int(float(number_str))
    except Exception:
        raise ValueError(f"Invalid number in frequency: {frequency}")

    kwargs = {}
    if unit in ("day", "days"):
        kwargs["days"] = value
    elif unit in ("hour", "hours"):
        kwargs["hours"] = value
    elif unit in ("minute", "minutes"):
        kwargs["minutes"] = value
    elif unit in ("second", "seconds"):
        kwargs["seconds"] = value
    elif unit in ("week", "weeks"):
        kwargs["weeks"] = value
    elif unit in ("month", "months"):
        kwargs["days"] = value * 30   # approximate month
    elif unit in ("year", "years"):
        kwargs["days"] = value * 365  # approximate year
    else:
        raise ValueError(f"Unknown time unit in frequency: {unit}")

    return datetime.timedelta(**kwargs)<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq:
        raise ValueError("Empty frequency")
    if freq.lower() == "always":
        return None
    parts = freq.split()
    if len(parts) < 2:
        raise ValueError(f"Invalid frequency format: {frequency}")
    # Assume the first part is the numeric value
    try:
        value = int(parts[0])
    except ValueError:
        # Try the last part if the first is not a number
        try:
            value = int(parts[-1])
            unit = parts[0]
        except ValueError:
            raise ValueError(f"Could not parse numeric value in frequency: {frequency}")
    else:
        unit = parts[1]
    unit = unit.lower().strip(".,;:!?")
    # Normalize plural forms
    if unit.endswith('s'):
        unit = unit[:-1]
    unit_map = {
        'day': ('days', ),
        'week': ('weeks', ),
        'hour': ('hours', ),
        'minute': ('minutes', ),
        'second': ('seconds', ),
        'millisecond': ('milliseconds', ),
        'microsecond': ('microseconds', ),
    }
    if unit not in unit_map:
        # Additionally try all singular/plural variants
        plural = unit + 's'
        if plural in unit_map:
            unit = plural
        elif unit in unit_map:
            pass
        else:
            raise ValueError(f"Unknown time unit: {unit}")
    kwargs = {unit_map[unit][0]: value}
    return datetime.timedelta(**kwargs)<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for info in addrinfo:
        family, _, _, _, sockaddr = info
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == "::1":
                return True
    return False<|return|>

