def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Handle common textual representations directly
    if host in ('localhost', '127.0.0.1', '::1'):
        return True

    try:
        # Resolve the host to its IP addresses
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # If the hostname cannot be resolved, fallback to name comparison
        addrinfo = []

    # Check if any resolved address is a loopback address
    for info in addrinfo:
        sockaddr = info[4]
        ip = sockaddr[0]
        if ip == '127.0.0.1' or ip == '::1':
            return True

    # Fallback: compare against the local machine's own hostname
    try:
        local_names = {socket.gethostname(), socket.getfqdn()}
    except Exception:
        local_names = set()

    if host in local_names:
        return True

    return False<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Resolve the host to all address info entries
        for family, _, _, _, sockaddr in socket.getaddrinfo(host, None):
            # IPv4 loopback
            if family == socket.AF_INET and sockaddr[0] == "127.0.0.1":
                return True
            # IPv6 loopback
            if family == socket.AF_INET6 and sockaddr[0] == "::1":
                return True
    except socket.gaierror:
        # If the host cannot be resolved we consider it not local
        return False
    return False<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    if host.lower() == "localhost":
        return True
    try:
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in addrinfo:
        ip = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4 loopback addresses start with 127.
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback address, strip any zone index
            ip_clean = ip.split("%")[0]
            if ip_clean == "::1":
                return True
    return False<|return|>

def is_gitbash():
    """returns True if you run in a Windows gitbash

