        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # In recent Python versions the compiled pattern type is re.Pattern
    compiled_type = getattr(re, "Pattern", None) or getattr(re, "_pattern_type", None)
    if isinstance(pattern, compiled_type):
        return pattern
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Prepare the command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]

    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(args)

    if verbose:
        print("Running command:", cmd)

    stderr_mode = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
