def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import re
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    config_map = {}
    error_logs = []
    env_var_pat = re.compile(r'\$\{([^}]+)\}')

    def _resolve_env(value):
        if isinstance(value, str):
            def repl(match):
                return os.environ.get(match.group(1), match.group(0))
            return env_var_pat.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    def _apply_overrides(cfg):
        if not overrides:
            return cfg
        if not isinstance(cfg, dict):
            return cfg
        for key, val in overrides.items():
            cfg[key] = val
        return cfg

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                raw = f.read()
            _, ext = os.path.splitext(fname)
            ext = ext.lower()
            cfg = None
            if ext in ('.yaml', '.yml', '.json'):
                if ext == '.json':
                    cfg = json.loads(raw)
                else:
                    if yaml is None:
                        raise ImportError('yaml module not available')
                    cfg = yaml.safe_load(raw)
            else:
                if yaml is None:
                    raise ImportError('yaml module not available')
                cfg = yaml.safe_load(raw)
            if cfg is None:
                cfg = {}
            cfg = _apply_overrides(cfg)
            if resolve_env:
                cfg = _resolve_env(cfg)
            config_map[fname] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f'Error parsing file {fname}: {e}',
                args=None,
                exc_info=None
            )
            error_logs.append(record)
            config_map[fname] = None

    return config_map, error_logs<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    log_records = []
    for fname in config_filenames:
        try:
            with open(fname, 'r') as fd:
                content = fd.read()
            ext = os.path.splitext(fname)[1].lower()
            if ext == '.toml':
                import toml
                cfg = toml.loads(content)
            elif ext in {'.yaml', '.yml'}:
                import yaml
                cfg = yaml.safe_load(content)
            elif ext == '.json':
                import json
                cfg = json.loads(content)
            else:
                raise ValueError(f"Unsupported config file extension: {ext}")

            if overrides:
                def deep_update(d, u):
                    for k, v in u.items():
                        if isinstance(v, dict) and isinstance(d.get(k), dict):
                            deep_update(d[k], v)
                        else:
                            d[k] = v
                deep_update(cfg, overrides)

            if resolve_env:
                import os
                def resolve(v):
                    if isinstance(v, str):
                        return os.path.expandvars(v)
                    elif isinstance(v, dict):
                        return {k: resolve(vv) for k, vv in v.items()}
                    elif isinstance(v, list):
                        return [resolve(i) for i in v]
                    else:
                        return v
                cfg = resolve(cfg)

            configs[fname] = cfg
        except Exception as exc:
            rec = logging.LogRecord(
                name="config_loader",
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=None
            )
            log_records.append(rec)
    return configs, log_records<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import logging
    import toml
    import yaml

    parsed_configs = {}
    error_records = []

    for cfg_file in config_filenames:
        try:
            with open(cfg_file, 'r') as fd:
                raw = fd.read()
            # Try TOML first
            try:
                cfg = toml.loads(raw)
            except Exception:
                try:
                    cfg = yaml.safe_load(raw)
                except Exception as e_yaml:
                    raise ValueError(f"YAML parsing error: {e_yaml}") from e_yaml
        except Exception as e:
            record = logging.LogRecord(
                name=cfg_file,
                level=logging.ERROR,
                pathname=cfg_file,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        # Apply environment variable resolution if requested
        if resolve_env:
            def _expand(value):
                if isinstance(value, str):
                    return os.path.expandvars(value)
                return value
            cfg = {k: _expand(v) for k, v in cfg.items()}

        # Apply overrides if provided
        if overrides:
            # Deep merge overrides over cfg
            def _merge_dict(base, override):
                for k, v in override.items():
                    if (
                        k in base
                        and isinstance(base[k], dict)
                        and isinstance(v, dict)
                    ):
                        _merge_dict(base[k], v)
                    else:
                        base[k] = v
            _merge_dict(cfg, overrides)

        parsed_configs[cfg_file] = cfg

    return parsed_configs, error_records<|return|>

