def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Helper to identify iterable but not a string or bytes
    def _is_iterable(x):
        return hasattr(x, "__iter__") and not isinstance(x, (str, bytes))

    # If seq itself is a sequence (e.g., list, tuple, generator), return it directly
    if _is_iterable(seq):
        return seq, type(seq)

    # If seq is a file‑like object, try to read its contents
    if hasattr(seq, "read"):
        try:
            data = seq.read(bufsize) if bufsize is not None else seq.read()
        except Exception:
            data = seq.read()
        return data, type(data)

    # Default: convert non‑iterable to a single‑item list
    return [seq], list<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        return (None, None)
    # Check for non-string iterables (list, tuple, etc.)
    if isinstance(seq, (list, tuple, set)):
        return (seq, type(seq).__name__)
    # Treat strings and bytes normally as sequences of characters
    if isinstance(seq, (str, bytes)):
        return (list(seq), type(seq).__name__)
    # For any other object, attempt to convert to a list
    try:
        seq_iter = list(seq)
        return (seq_iter, type(seq).__name__)
    except Exception:
        # Not iterable; wrap in a singleton list
        return ([seq], type(seq).__name__)<|return|>

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.
    """
    # Helper to collect errors
    errors = []

    # Ensure candidate is a class or instance
    cls = candidate if isinstance(candidate, type) else type(candidate)

    # 1. Check that candidate declares that it provides the interface
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception as exc:
            provided = False
            errors.append(f"Error checking providedBy: {exc}")
        if not provided:
            errors.append(f"Candidate {cls!r} does not provide interface {iface!r}")

    # 2. Gather required methods and attributes
    # Interface has _requiredMethods and _requiredAttributes
    try:
        required_methods = getattr(iface, "_requiredMethods")
    except AttributeError:
        required_methods = []

    try:
        required_attrs = getattr(iface, "_requiredAttributes")
    except AttributeError:
        required_attrs = []

    # 3. Check each required method
    for name in required_methods:
        if not hasattr(cls, name):
            errors.append(f"Method {name!r} missing in candidate {cls!r}")
            continue
        attr_candidate = getattr(cls, name)
        if not callable(attr_candidate):
            errors.append(f"Attribute {name!r} of candidate {cls!r} is not callable")
            continue
        # Compare signatures if possible
        try:
            iface_sig = inspect.signature(getattr(iface, name))
            cand_sig = inspect.signature(attr_candidate)
            # Simple comparison: number of parameters and kind of each
            iface_params = list(iface_sig.parameters.values())
            cand_params = list(cand_sig.parameters.values())
            if len(iface_params) != len(cand_params):
                errors.append(
                    f"Signature mismatch for method {name!r}: expected {len(iface_params)} "
                    f"parameters, got {len(cand_params)}"
                )
            else:
                for ip, cp in zip(iface_params, cand_params):
                    if ip.kind != cp.kind:
                        errors.append(
                            f"Signature mismatch for method {name!r}: parameter {ip.name} "
                            f"has kind {ip.kind} in interface, but {cp.kind} in candidate"
                        )
                        break
        except Exception as exc:
            errors.append(f"Error inspecting signature of {name!r}: {exc}")

    # 4. Check each required attribute
    for name in required_attrs:
        if not hasattr(cls, name):
            errors.append(f"Attribute {name!r} missing in candidate {cls!r}")

    # 5. Raise errors or return True
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("; ".join(errors))
    return True
<|return|>

def verifyObject(iface, candidate, tentative=False):
    import inspect
    import zope.interface

    errors = []

    # Check that the candidate claims to provide the interface
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate!r} does not provide {iface!r}")

    # Check that all interface attributes/methods exist on the candidate
    for name in iface:
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute: {name}")
            continue

        candidate_attr = getattr(candidate, name)
        iface_attr = getattr(iface, name, None)

        # If the interface declares a method, verify signature
        if inspect.isroutine(iface_attr):
            if not inspect.isroutine(candidate_attr):
                errors.append(
                    f"Expected method for {name} but got {type(candidate_attr).__name__}"
                )
                continue
            try:
                iface_sig = inspect.signature(iface_attr)
                candidate_sig = inspect.signature(candidate_attr)
                if iface_sig != candidate_sig:
                    errors.append(
                        f"Signature mismatch for {name}: interface {iface_sig}, candidate {candidate_sig}"
                    )
            except Exception as exc:
                errors.append(f"Could not inspect signature for {name}: {exc}")
        else:
            # For interface attributes (non-methods), we've already confirmed existence
            pass

    # Report errors, following version 5.0 behavior
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        raise zope.interface.Invalid("\n".join(errors))

    return True<|return|>

