            # Compare parameter lists (ignoring return annotation)
            def _sig_repr(sig):
                return [ (p.name, p.kind, p.default) for p in sig.parameters.values() ]
            if _sig_repr(iface_sig) != _sig_repr(impl_sig):
                errors.append(
                    f"Signature of method '{name}' for {candidate!r} "
                    f"does not match that defined by {iface!r}"
                )

    # Step 4: Check for other required attributes (non-callables)
    for name, value in iface.__dict__.items():
        if name.startswith('_'):
            continue
        if not (isfunction(value) or ismethod(value)):
            if not hasattr(candidate, name):
                errors.append(f"Candidate missing required attribute '{name}' for {iface!r}")

    # Final error handling
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple interface verification errors:\n" + "\n".join(errors))

    return True<|return|>

