def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    The verification checks that the candidate class or instance implements
    all public attributes and methods defined on *iface*.  If *tentative* is
    ``True`` the function returns ``False`` rather than raising an exception
    when the candidate does not satisfy the interface.  Otherwise it raises
    a :class:`TypeError` describing the missing attributes.
    """
    # Resolve the type of the candidate (class or instance)
    if isinstance(candidate, type):
        target = candidate
    else:
        target = type(candidate)

    # Quick subclass check for concrete classes
    try:
        if inspect.isclass(iface) and inspect.isclass(target) and issubclass(target, iface):
            return True
    except Exception:
        # ignore if introspection fails
        pass

    missing = []
    for name in dir(iface):
        if name.startswith('_'):  # skip private / special attributes
            continue
        if not hasattr(target, name):
            missing.append(name)

    if missing:
        msg = f"{target.__name__ if isinstance(target, type) else target} does not implement required attributes or methods: {', '.join(missing)}"
        if tentative:
            return False
        raise TypeError(msg)

    return True<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if not bases:
        # No bases: return explicit metaclass if specified, otherwise the default `type`
        return explicit_mc if explicit_mc is not None else type

    # Start with the metaclass of the first base
    try:
        metaclass = type(bases[0])
    except TypeError as exc:
        raise TypeError(f"Base {bases[0]!r} does not have a metaclass") from exc

    # Resolve the most derived metaclass among all bases
    for base in bases[1:]:
        try:
            base_meta = type(base)
        except TypeError as exc:
            raise TypeError(f"Base {base!r} does not have a metaclass") from exc

        if metaclass is type:
            metaclass = base_meta
            continue

        if issubclass(base_meta, metaclass):
            # existing metaclass is already a subclass of the new one; keep it
            continue
        if issubclass(metaclass, base_meta):
            # the new metaclass is more derived; use it
            metaclass = base_meta
            continue

        # No clear relationship – conflict
        raise TypeError(
            f"metaclass conflict: {metaclass.__name__} vs {base_meta.__name__}"
        )

    # If an explicit metaclass is given, ensure it is compatible
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit __metaclass__ must be a type")
        if issubclass(explicit_mc, metaclass):
            # Explicit is more derived – use it
            metaclass = explicit_mc
        elif not issubclass(metaclass, explicit_mc):
            # Neither is a subclass of the other – conflict
            raise TypeError(
                f"metaclass conflict between {metaclass.__name__} "
                f"and explicit __metaclass__ {explicit_mc.__name__}"
            )

    return metaclass<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__.

    The algorithm follows the CPython rules for computing the class
    metaclass.  If an explicit metaclass is supplied it must be a
    subclass of all metaclasses of the bases.  When no explicit
    metaclass is given, the most derived metaclass of the bases
    is selected.  If a conflict cannot be resolved a ``TypeError``
    is raised.
    """
    # If an explicit metaclass is supplied, confirm compatibility.
    if explicit_mc is not None:
        for base in bases:
            if not issubclass(explicit_mc, type(base)):
                raise TypeError(
                    f"metaclass {explicit_mc.__name__} conflicts with "
                    f"base {base.__name__} metaclass {type(base).__name__}"
                )
        return explicit_mc

    # No explicit metaclass; compute from bases.
    if not bases:
        return type

    base_meta = type(bases[0])
    for base in bases[1:]:
        current_meta = type(base)
        if issubclass(base_meta, current_meta):
            continue
        if issubclass(current_meta, base_meta):
            base_meta = current_meta
        else:
            raise TypeError(
                f"metaclass conflict: {current_meta.__name__} "
                f"is not a subclass of {base_meta.__name__}"
            )
    return base_meta<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass was provided, use it directly.
    if explicit_mc is not None:
        return explicit_mc

    # When no bases are given we fall back to ``object``.
    if not bases:
        return object

    # Collect the metaclasses of all bases.
    # ``type(b)`` gives the metaclass of ``b``.
    metaclasses = set(type(b) for b in bases)

    # If all bases share the same metaclass, return it.
    if len(metaclasses) == 1:
        return metaclasses.pop()

    # Resolve a single metaclass from multiple candidates.
    # The chosen metaclass must be a subclass of every other candidate.
    selected = None
    for mc in metaclasses:
        if all(issubclass(mc, other) for other in metaclasses):
            # Prefer the most-derived metaclass if more than one satisfies the condition.
            if selected is None or issubclass(mc, selected):
                selected = mc

    if selected is None:
        raise TypeError(
            "metaclass conflict: no common ancestor "
            f"for bases {tuple(b.__name__ for b in bases)}"
        )

    return selected<|return|>

