def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime.datetime):
        raise TypeError('dt must be a datetime instance')
    # Ensure UTC time
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)
    # ISO8601 with milliseconds and trailing Z
    # "%Y-%m-%dT%H:%M:%S.%f" gives microseconds; slice to milliseconds
    s = dt.strftime("%Y-%m-%dT%H:%M:%S.%f")[:23] + "Z"
    return s<|return|>

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    _URL_RE = re.compile(r'''(?x)
        (https?://[^\s]+)                 # http(s) URLs
      | (\/?[^\s]+)                       # simple paths starting with slash or none
    ''')
    def replace(match):
        url = match.group(0)
        href = None
        if url.startswith('http://') or url.startswith('https://'):
            href = url
        elif url.startswith('/') or url.startswith('./') or url.startswith('../'):
            path = url.lstrip('/')
            abs_path = os.path.abspath(os.path.join(os.getcwd(), path))
            if os.path.exists(abs_path):
                rel_path = os.path.relpath(abs_path, os.getcwd()).replace(os.sep, '/')
                href = '/browse/' + rel_path
        else:
            abs_path = os.path.abspath(os.path.join(os.getcwd(), url))
            if os.path.exists(abs_path):
                rel_path = os.path.relpath(abs_path, os.getcwd()).replace(os.sep, '/')
                href = '/browse/' + rel_path
        if href:
            return f'<a target="_blank" href="{href}">{url}</a>'
        else:
            return url
    return _URL_RE.sub(replace, text)<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if scheme not in ('http', 'https'):
        return None
    # Construct a HEAD request
    req = urllib.request.Request(url, method='HEAD', headers={'Host': netloc})
    try:
        resp = urllib.request.urlopen(req)
        # Return the Content-Type header if present
        return resp.info().get('content-type')
    except Exception:
        # Any error (connection, DNS, HTTP error, etc.) yields no content type
        return None
    finally:
        try:
            resp.close()
        except Exception:
            pass<|return|>

