        root = etree.fromstring(doc.encode('utf-8'), parser)
    except Exception:
        return False

    # Locate the Signature element
    ns = {'dsig': 'http://www.w3.org/2000/09/xmldsig#'}
    sig_node = root.find('.//dsig:Signature', ns)
    if sig_node is None:
        return False

    # Load the public key for verification
    try:
        key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
    except Exception:
        return False

    # Verify the signature
    ctx = xmlsec.SignatureContext()
    ctx.key = key
    try:
        return ctx.verify(sig_node)
    except xmlsec.VerificationError:
        return False
