        # Namespace handling (common for XRD)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        subject_el = root.find(".//Subject", ns) or root.find(".//xrd:Subject", ns)
        if subject_el is not None:
            result["subject"] = subject_el.text
        id_el = root.find(".//Id", ns) or root.find(".//xrd:Id", ns)
        if id_el is not None:
            result["id"] = id_el.text
        for link_el in root.findall(".//Link", ns) + root.findall(".//xrd:Link", ns):
            href = link_el.get("href")
            rel = link_el.get("rel", "")
            if "hcard" in rel:
                result["hcard_url"] = href
            elif "profile" in rel:
