def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        if not isinstance(data, dict):
            return None

        # Extract hCard URL from links or properties if not already present
        if "hcard_url" not in data:
            hcard = None
            # Check link entries
            for link in data.get("links", []):
                rel = link.get("rel", "")
                if "hcard" in rel.lower() or "profile/hcard" in rel:
                    hcard = link.get("href")
                    break
            # Check properties map
            if not hcard and "properties" in data:
                hcard = data["properties"].get("http://microformats.org/profile/hcard")
                if not hcard:
                    hcard = data["properties"].get("http://purl.org/oauth/endpoint")  # fallback
            if hcard:
                data["hcard_url"] = hcard
        return data

    except Exception:
        # Fall back to XRD (XML) parsing
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            subject_el = root.find("xrd:Subject", ns)
            subject = subject_el.text if subject_el is not None else None

            aliases = [
                alias.text
                for alias in root.findall("xrd:Alias", ns)
                if alias.text is not None
            ]

            hcard_url = None
            for link in root.findall("xrd:Link", ns):
                rel = link.attrib.get("rel", "")
                href = link.attrib.get("href")
                if rel and href:
                    if "hcard" in rel.lower() or "profile/hcard" in rel:
                        hcard_url = href
                        break

            result: Dict = {}
            if subject:
                result["subject"] = subject
            if aliases:
                result["aliases"] = aliases
            if hcard_url:
                result["hcard_url"] = hcard_url
            return result or None
        except Exception:
            return None<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return {}

    # Trim whitespace to avoid JSON parse errors.
    doc = document.strip()

    # First try to parse as JSON.
    if doc.startswith('{'):
        try:
            return json.loads(doc)
        except Exception:
            # Fall back to XRD parsing if JSON fails.
            pass

    # Attempt to parse as XRD (XML).
    try:
        root = ElementTree.fromstring(doc)
    except Exception:
        # If we cannot parse the XML, return empty dict.
        return {}

    # Namespace handling – XRD can be in the official namespace or no namespace.
    ns = {'xrd': 'http://docs.oasis-open.org/legaldoc/legaldoc/xrd/0.2'}

    # Extract subject.
    subject = None
    subject_el = root.find('xrd:Subject', ns)
    if subject_el is None:
        subject_el = root.find('Subject')
    if subject_el is not None:
        subject = subject_el.text

    # Extract `<Link>` elements.
    links = []
    # Try namespaced and non-namespaced `<Link>`.
    for prefix in ('xrd', ''):
        for link_el in root.findall(f'{prefix}:Link' if prefix else 'Link'):
            rel = link_el.attrib.get('rel')
            href = link_el.attrib.get('href')
            title = link_el.attrib.get('title')
            if rel and href:
                link_dict = {'rel': rel, 'href': href}
                if title:
                    link_dict['title'] = title
                links.append(link_dict)

    # Build result.
    result: Dict[str, Any] = {}
    if subject:
        result['subject'] = subject
    if links:
        result['links'] = links
    return result
