def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
    except Exception:
        data = None

    if data is not None:
        # JSON format – return the parsed object, adding a convenient hcard_url field if present.
        result: Dict = {}
        if "subject" in data:
            result["subject"] = data["subject"]
        if "aliases" in data:
            result["aliases"] = data["aliases"]
        if "properties" in data:
            result["properties"] = data["properties"]
        if "links" in data:
            result["links"] = data["links"]
            # Extract hcard_url for quick access
            for link in data["links"]:
                if isinstance(link, dict) and link.get("rel") == "hcard":
                    result["hcard_url"] = link.get("href")
                    break
        return result

    # Fallback to XRD format (XML)
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return None

    ns = {"x": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
    result: Dict = {}

    subj = root.find("x:Subject", ns)
    if subj is not None and subj.text:
        result["subject"] = subj.text.strip()

    aliases = []
    for alias in root.findall("x:Alias", ns):
        if alias.text:
            aliases.append(alias.text.strip())
    if aliases:
        result["aliases"] = aliases

    links = []
    for link in root.findall("x:Link", ns):
        link_dict: Dict = {}
        if "rel" in link.attrib:
            link_dict["rel"] = link.attrib["rel"]
        if "href" in link.attrib:
            link_dict["href"] = link.attrib["href"]
        if "template" in link.attrib:
            link_dict["template"] = link.attrib["template"]
        if link_dict:
            links.append(link_dict)
    if links:
        result["links"] = links
        # Extract hcard_url
        for l in links:
            if l.get("rel") == "hcard":
                result["hcard_url"] = l.get("href")
                break

    return result if result else None<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Extract host part of the handle
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        # Handle is not in the expected "user@host" format
        return None

    # Construct the webfinger URL
    url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"

    try:
        with closing(urllib.request.urlopen(url)) as resp:
            if resp.getcode() == 200:
                # Return the document as a string
                return resp.read().decode("utf-8")
            else:
                return None
    except (urllib.error.HTTPError, urllib.error.URLError, ValueError):
        # Any network or decoding error should result in None
        return None<|return|>

