def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        file_names = []
        for directory in settings_dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                # if spec_option looks like an extension, e.g., ".ini"
                if spec_option.startswith('.'):
                    if fname.endswith(spec_option):
                        file_names.append(os.path.join(directory, fname))
                else:
                    # treat spec_option as a glob pattern
                    if fnmatch.fnmatch(fname, spec_option):
                        file_names.append(os.path.join(directory, fname))
        return sorted(file_names)
    except Exception:
        return []<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    file_list = []

    for directory in settings_dirs:
        if not isinstance(directory, str):
            continue
        if not os.path.isdir(directory):
            continue

        for root, _, files in os.walk(directory):
            for fname in files:
                try:
                    if spec_option:
                        # spec_option may be a wildcard pattern or extension
                        if fnmatch.fnmatch(fname, spec_option):
                            file_list.append(os.path.join(root, fname))
                    else:
                        file_list.append(os.path.join(root, fname))
                except Exception:
                    # Skip any problematic file
                    continue

    return sorted(file_list)<|return|>

