def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        return parser_dict
    include = parser_dict.pop('include', None)
    if include is None:
        return parser_dict
    if isinstance(include, dict):
        # Directly merge key/value pairs from the include dict
        for key, value in include.items():
            parser_dict.setdefault(key, value)
    elif isinstance(include, str):
        import os, yaml
        # Expand user tilde and handle relative paths
        path = os.path.expanduser(include)
        if not os.path.isabs(path):
            # try relative to the calling file's directory
            cwd = os.getcwd()
            path = os.path.join(cwd, path)
        if not os.path.exists(path):
            raise FileNotFoundError(f"Included spec file not found: {path}")
        with open(path, 'r') as f:
            included = yaml.safe_load(f)
        # Resolve any nested includes recursively
        included = self._include_groups(included)
        for key, value in included.items():
            parser_dict.setdefault(key, value)
    return parser_dict<|return|>

def _include_groups(self, parser_dict):
    """Resolves the `include` dict directive in the spec files."""
    include_directive = parser_dict.pop("include", {})
    if not isinstance(include_directive, dict):
        return parser_dict
    for group_name, spec_source in include_directive.items():
        if isinstance(spec_source, str):
            # Load spec from a file.  We assume YAML or JSON formats.
            if spec_source.endswith(".yaml") or spec_source.endswith(".yml"):
                with open(spec_source, "r") as f:
                    included_data = yaml.safe_load(f)
            else:
                with open(spec_source, "r") as f:
                    included_data = json.load(f)
        elif isinstance(spec_source, dict):
            included_data = spec_source
        else:
            raise ValueError(
                f"Unsupported include spec for group {group_name!r}: {spec_source!r}"
            )
        # Recursively resolve any nested include directives inside the included data.
        self._include_groups(included_data)
        if group_name in parser_dict:
            parser_dict[group_name].update(included_data)
        else:
            parser_dict[group_name] = included_data
    return parser_dict<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # make a shallow copy so we don't modify the input dictionary
    resolved = dict(parser_dict)

    # helper to recursively merge a spec that contains an 'include' key
    def merge_spec(key, spec, visited=None):
        if visited is None:
            visited = set()
        # avoid infinite recursion in case of circular includes
        if key in visited:
            return spec
        visited.add(key)

        if not isinstance(spec, dict) or 'include' not in spec:
            return spec

        includes = spec.pop('include')
        # supports include as a dict of other specs or a list of keys
        if isinstance(includes, dict):
            for inc_key, inc_val in includes.items():
                # if the referenced key is present in the top‑level dict, merge it
                if inc_key in resolved and isinstance(resolved[inc_key], dict):
                    merged_inc = merge_spec(inc_key, resolved[inc_key], visited)
                    spec.update(merged_inc)
        elif isinstance(includes, list):
            for inc_key in includes:
                if inc_key in resolved and isinstance(resolved[inc_key], dict):
                    merged_inc = merge_spec(inc_key, resolved[inc_key], visited)
                    spec.update(merged_inc)
        return spec

    # Resolve includes for each top‑level key
    for key in list(resolved):
        resolved[key] = merge_spec(key, resolved[key])

    return resolved<|return|>

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        def _resolve_group(name, seen=None):
            if seen is None:
                seen = set()
            if name in seen:
                raise RuntimeError('Circular include detected: {}'.format(' -> '.join(list(seen) + [name])))
            seen.add(name)
            group = parser_dict.get(name)
            if group is None:
                raise KeyError('Referenced group {!r} not found'.format(name))
            # Copy to avoid mutating while iterating
            if not isinstance(group, dict):
                raise TypeError('Group definition of {!r} must be a dict, got {}'.format(name, type(group)))
            include = group.pop('include', None)
            if include:
                # Normalise to iterable
                if isinstance(include, str):
                    include = [include]
                elif not isinstance(include, (list, tuple)):
                    raise TypeError('include value for group {!r} must be a string or list, got {}'.format(name, type(include)))
                merged = {}
                for inc in include:
                    inc_dict = _resolve_group(inc, seen=seen.copy())
                    for k, v in inc_dict.items():
                        # only add if key not already defined in the current group
                        if k not in merged and k not in group:
                            merged[k] = v
                # Merge included attributes into group, but keep original group's definitions
                for k, v in merged.items():
                    if k not in group:
                        group[k] = v
            return group

        # Resolve all groups in the dictionary
        for key in list(parser_dict.keys()):
            _resolve_group(key)<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    resolved = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue
        name = arg.name
        val = None
        # Try to get the value from the spec
        try:
            val = self.spec[name]
        except (KeyError, TypeError):
            # Fall back to the default spec if available
            try:
                val = self._default_spec[name]
            except (AttributeError, KeyError, TypeError):
                val = None

        # If no value found, use the option's default
        if val is None:
            if not isinstance(arg.default, NoDefault):
                val = arg.default
            else:
                continue  # No value at all

        # Handle nested DictOption schemes
        if isinstance(arg, DictOption) and isinstance(val, dict) and arg.scheme:
            try:
                nested = arg.scheme.get_spec_defaults()
            except Exception:
                nested = {}
            # Merge nested defaults with overridden values
            nested.update(val)
            val = nested

        resolved[name] = val
    return resolved<|return|>

def get_spec_defaults(self):
