    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Try to get a value from the spec, which may be an object or a dictionary.
        val = None
        try:
            val = getattr(self.spec, arg.name)
        except AttributeError:
            if isinstance(self.spec, dict):
                val = self.spec.get(arg.name)

        # Fall back to the option's own default if the spec did not provide a value.
        if val is None and not isinstance(arg.default, NoDefault):
            val = arg.default

        # If a value was obtained, store it. Otherwise skip this key.
        if val is not None:
            defaults[arg.name] = val

        # If the option is a DictOption, recursively resolve defaults from its scheme.
        if isinstance(arg, DictOption) and arg.scheme:
            try:
                nested = arg.scheme.get_spec_defaults()
            except AttributeError:
                # Scheme may not expose get_spec_defaults; skip recursion.
                nested = {}
            if nested:
                defaults[arg.name] = nested

    return defaults<|return|>

def get_spec_defaults(self):
