        # Fallback to option's default if it exists
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
        else:
            defaults[arg.name] = None

        # Handle nested DictOption by recursing into its scheme
        if isinstance(arg, DictOption) and arg.scheme:
            nested_defaults = arg.scheme.get_spec_defaults()
            if nested_defaults:
