def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # `deprecated_args` should be a mapping from old argument names to
        # current names, e.g. {'old_opt': 'new_opt'}
        deprecated_map = getattr(self, 'deprecated_args', {})
        if not deprecated_map:
            return  # nothing to validate

        for src_name, args in [('command line', cli_args), ('answer file', answer_file_args)]:
            for old, new in deprecated_map.items():
                if old in args:
                    print(
                        f"WARNING: In {src_name}, argument '{old}' is deprecated; "
                        f"please use '{new}' instead."
                    )
                    # Optionally migrate the value to the new key
                    if new not in args:
                        args[new] = args[old]
                    del args[old]
                elif new in args and old in args:  # both provided
                    print(
                        f"ERROR: In {src_name}, both deprecated argument '{old}' "
                        f"and its replacement '{new}' are provided. "
                        f"Please remove the deprecated one."
                    )
                    # Prefer the new argument; keep only new
                    del args[old]<|return|>

