def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    skip_next = False
    for i, arg in enumerate(args):
        if skip_next:
            skip_next = False
            continue
        if arg.startswith('-'):
            # If the next element exists and is not another option,
            # this argument expects a value, so we skip it.
            if i + 1 < len(args) and not args[i + 1].startswith('-'):
                skip_next = True
            else:
                silent_args.append(arg)
    return silent_args<|return|>

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    if isinstance(args, (list, tuple)):
        for a in args:
            if isinstance(a, str) and a.startswith('-') and ('quiet' in a or 'silent' in a):
                silent.append(a)
    else:
        try:
            d = vars(args)
        except Exception:
            d = {}
        for k, v in d.items():
            if isinstance(v, bool) and v and ('quiet' in k or 'silent' in k):
                silent.append(k)
    return silent<|return|>

def get_silent_args(self, args):
