    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_names = []
    # Handle a mapping (e.g., dict) or Namespace-like object
    if isinstance(args, dict):
        items = args.items()
    else:
        # Try to get attributes from a Namespace or similar object
        items = vars(args).items() if hasattr(args, "__dict__") else []
    for name, value in items:
        # Consider boolean flags that are truthy and specifically named 'quiet' or 'silent'
        if isinstance(value, bool) and value:
            if name.lower() in ("quiet", "silent", "quiet_mode", "silent_mode"):
                silent_names.append(name)
    return silent_names<|return|>

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    # Handle mapping types (e.g., dict or Namespace)
    if hasattr(args, 'items'):
        iterator = args.items()
    else:
        # Assume iterable of key-value tuples or just keys
        try:
            iterator = [(k, v) for k, v in args]
        except Exception:
            iterator = [(str(a), None) for a in args]

    for key, val in iterator:
        # An argument is considered "silenced" if its value is None or bool False
        if val is None or val is False:
