def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list of argument names whose ``required_when`` condition is true
    """
    required = []
    for opt in options_spec:
        # skip options without a required_when condition
        cond = opt.get('required_when')
        if cond is None:
            continue

        # determine the name of the option; fallback on common keys
        name = opt.get('name') or opt.get('dest') or opt.get('arg') or opt.get('option')
        if not name:
            # can't determine a name, skip this option
            continue

        try:
            # If the condition is callable, call it with command_name and args
            # otherwise treat it as a truthy value
            if callable(cond):
                if cond(command_name, args):
                    required.append(name)
            else:
                if cond:
                    required.append(name)
        except Exception:
            # When evaluating the condition raises an exception the option
            # is simply ignored; the caller can decide how to handle such
            # situations.
            continue

    return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_names = []
    for opt in options_spec:
        # Get the condition and the option name in a robust way
        cond = getattr(opt, "required_when", None)
        if cond is None:
            continue

        # Determine if the condition matches the current command and args
        matched = False
        try:
            if callable(cond):
                # If it's a function or lambda, call it with command_name and args
                matched = cond(command_name, args)
            elif isinstance(cond, dict):
                # If it's a dict, treat keys as command names
                matched = bool(cond.get(command_name, False))
            elif isinstance(cond, (set, list)):
                # If it's a set/list, check membership of command_name
                matched = command_name in cond
            else:
                # Otherwise, treat the value as a boolean or truthy value
                matched = bool(cond)
        except Exception:
            # In case the condition callable throws, ignore and treat as unmatched
            matched = False

        if matched:
            # Prefer a ``name`` attribute, fall back to ``arg`` or string representation
            opt_name = getattr(opt, "name", None)
            if opt_name is None:
                opt_name = getattr(opt, "arg", None)
                if opt_name is None:
                    opt_name = str(opt)
            required_names.append(opt_name)

    return required_names<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
