    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        cond = opt.get('required_when')
        if cond is None:
            continue
        match = False
        # If the condition is a callable, evaluate it with command_name and args
        if callable(cond):
            try:
                match = bool(cond(command_name, args))
            except Exception:
                match = False
        # If the condition is an iterable (list, tuple, set), treat it as
        # acceptable command names
        elif isinstance(cond, (list, tuple, set)):
            match = command_name in cond
        else:
            # Otherwise, assume a single command name to compare against
            match = command_name == cond
        if match:
            name = opt.get('name')
            if name:
                required.append(name)
    return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for spec in options_spec:
        name = spec.get('name')
        cond = spec.get('required_when')
        if not cond:
            continue
        matched = False
        # callable condition
        if callable(cond):
            try:
                matched = bool(cond(command_name, args))
            except TypeError:
                matched = bool(cond(args))
        # dict condition: key -> expected value
        elif isinstance(cond, dict):
            for k, v in cond.items():
                if args.get(k) == v:
                    matched = True
                    break
        # iterable of conditions
        elif isinstance(cond, (list, tuple, set)):
            for c in cond:
                if callable(c):
                    try:
                        matched = bool(c(command_name, args))
                    except TypeError:
                        matched = bool(c(args))
                else:
                    if args.get(c):
                        matched = True
                if matched:
                    break
        # string condition
        elif isinstance(cond, str):
            if args.get(cond):
                matched = True
        if matched and name:
            required.append(name)
    return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg_name, arg_attrs in args.items():
        # The value of the argument
        value = arg_attrs.get('value')
        # The maximum allowed length for this argument
        max_len = arg_attrs.get('length')
        if max_len is None or value is None:
            continue
        # Only sequences support length checking
        try:
            if len(value) > max_len:
                raise ValueError(
                    f"Argument '{arg_name}' exceeds maximum length of {max_len}"
                )
        except TypeError:
            # Value doesn't have a length (e.g., int, float); ignore
            continue
