    :param args: The received arguments.
    """
    # args can be a mapping of arg name to attributes or a list of such dictionaries
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, list):
        items = [(list(ad.items())[0][0], list(ad.items())[0][1]) for ad in args]
    else:
        raise TypeError('args must be a dict or a list of single-item dictionaries')

    for arg_name, arg_attrs in items:
        # If attributes are provided as a dict, extract the value and length limit
        if isinstance(arg_attrs, dict):
            value = arg_attrs.get('value')
            # look for common length constraint keys
            max_len = arg_attrs.get('max_length') or arg_attrs.get('max_len') or arg_attrs.get('max')
            if max_len is not None:
                if hasattr(value, '__len__'):
                    actual_len = len(value)
                    if actual_len > max_len:
                        raise ValueError(
                            f"Argument '{arg_name}' length {actual_len} exceeds maximum allowed {max_len}"
                        )
                else:
                    # Value does not support len(); ignore or could issue warning
                    pass
        else:
            # arg_attrs is directly the value, no length constraint to verify
            pass
    return True<|return|>

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # `self.choices` should be a dict mapping argument names to
        # iterable collections (or sets) of allowed values.
        if not hasattr(self, 'choices'):
            return  # nothing to validate

        for arg_name, arg_value in args.items():
            if arg_name not in self.choices:
                continue

            allowed = self.choices[arg_name]
            if isinstance(arg_value, (list, tuple, set)):
                for v in arg_value:
                    if v not in allowed:
                        raise ValueError(
                            f"Invalid value for choice argument '{arg_name}': "
                            f"{v}. Allowed values are: {sorted(allowed)}"
                        )
            else:
                if arg_value not in  allowed:
                    raise ValueError(
                        f"Invalid value for choice argument '{arg_name}': "
                        f"{arg_value}. Allowed values are: {sorted(allowed)}"
                    )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Determine where valid choices are stored. Commonly a mapping of arg
    # names to an iterable of allowed values. If no such attribute exists
    # we simply skip validation.
    choices_map = getattr(self, "choices", {})
    if not isinstance(choices_map, dict):
        return  # nothing to validate

    for arg_name, value in args.items():
        if arg_name not in choices_map:
            continue

        allowed = choices_map[arg_name]
        # Normalize allowed to a set for efficient membership tests.
        try:
            allowed_set = set(allowed)
        except TypeError:
            # If allowed is a single value, treat it as a singleton set.
            allowed_set = {allowed}

        # Value may be a single element or an iterable (e.g., list of values).
        # Treat a bare string as a scalar value unless it is itself an
        # iterable in the sense of a container type.
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed_set:
                    msg = f"Invalid choice for '{arg_name}': {v!r}. Allowed: {sorted(allowed_set)}"
                    raise ValueError(msg)
        else:
            if value not in allowed_set:
                msg = f"Invalid choice for '{arg_name}': {value!r}. Allowed: {sorted(allowed_set)}"
                raise ValueError(msg)<|return|>

def validate_choices_args(self, args):
