    :param args: The received arguments.
    """
    arg_defs = self.parsed_yaml.get('args', {})
    if isinstance(arg_defs, dict):
        for argn, argattrs in arg_defs.items():
            if not isinstance(argattrs, dict):
                continue
            choices = argattrs.get('choices')
            if choices and argn in args:
                val = args[argn]
                if val not in choices:
                    msg = (
                        f"Invalid value for argument '{argn}': "
                        f"'{val}'. Expected one of: {choices}"
                    )
                    raise ConfigurationError(msg)
    else:  # list of single‑item dicts
        for argdict in arg_defs:
            if not isinstance(argdict, dict):
                continue
            key, attrs = list(argdict.items())[0]
            if not isinstance(attrs, dict):
                continue
            choices = attrs.get('choices')
            if choices and key in args:
                val = args[key]
                if val not in choices:
                    msg = (
                        f"Invalid value for argument '{key}': "
                        f"'{val}'. Expected one of: {choices}"
                    )
                    raise ConfigurationError(msg)<|return|>

