def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")
    for i, item in enumerate(args):
        # Accept a dict or a 3‑tuple/list: (value, min, max)
        if isinstance(item, dict):
            value = item.get('value')
            min_ = item.get('min')
            max_ = item.get('max')
        elif isinstance(item, (tuple, list)) and len(item) == 3:
            value, min_, max_ = item
        else:
            continue  # skip items that don't carry min/max info
        if value is None:
            continue
        if min_ is not None and value < min_:
            raise ValueError(f"Argument {i} value {value} is less than minimum {min_}")
        if max_ is not None and value > max_:
            raise ValueError(f"Argument {i} value {value} is greater than maximum {max_}")
    return args<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for idx, arg in enumerate(args):
        # Resolve value, min, and max from various possible structures
        if isinstance(arg, dict):
            value = arg.get("value")
            min_val = arg.get("min")
            max_val = arg.get("max")
        elif isinstance(arg, (list, tuple)):
            # Expect format: (value,) or (value, min) or (value, min, max)
            value = arg[0] if len(arg) > 0 else None
            min_val = arg[1] if len(arg) > 1 else None
            max_val = arg[2] if len(arg) > 2 else None
        else:
            value = getattr(arg, "value", None)
            min_val = getattr(arg, "min", None)
            max_val = getattr(arg, "max", None)

        # Nothing to validate if no value is provided
        if value is None:
            continue

        # Validate that min is not greater than max
        if (min_val is not None) and (max_val is not None) and (min_val > max_val):
            raise ValueError(
                f"Argument {idx} has min ({min_val}) greater than max ({max_val})"
            )

        # Perform the min/max checks
        if (min_val is not None) and (value < min_val):
            raise ValueError(
                f"Argument {idx} value ({value}) is less than the minimum ({min_val})"
            )
        if (max_val is not None) and (value > max_val):
            raise ValueError(
                f"Argument {idx} value ({value}) is greater than the maximum ({max_val})"
            )
    return args<|return|>

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Each argument can be either
        a (value, min, max) tuple/list, or an object with ``value``,
        ``min``, and ``max`` attributes.

    :raises TypeError: If an argument does not provide the expected
        value/min/max information.
    :raises ValueError: If the value is outside its allowed range.
    """
    for idx, arg in enumerate(args):
        # Extract value, min and max
        if isinstance(arg, (tuple, list)) and len(arg) == 3:
            value, min_val, max_val = arg
        elif hasattr(arg, "value") and hasattr(arg, "min") and hasattr(arg, "max"):
            value = getattr(arg, "value")
            min_val = getattr(arg, "min")
            max_val = getattr(arg, "max")
        else:
            raise TypeError(
                f"Argument at position {idx} must be a (value, min, max) tuple "
                "or an object with 'value', 'min', and 'max' attributes."
            )

        # Validate min <= max
        if (
            min_val is not None
            and max_val is not None
            and min_val > max_val
        ):
            raise ValueError(
                f"Argument {idx}: minimum {min_val} cannot be greater than "
                f"maximum {max_val}."
            )

        # Validate value against bounds
        if min_val is not None and value < min_val:
            raise ValueError(
                f"Argument {idx} value {value} is below the minimum {min_val}."
            )
        if max_val is not None and value > max_val:
            raise ValueError(
                f"Argument {idx} value {value} is above the maximum {max_val}."
            )
    return None<|return|>

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        # Ensure the object defines limits
        if not hasattr(self, 'min') or not hasattr(self, 'max'):
            raise AttributeError("Object must define 'min' and 'max' attributes for validation")
        min_val, max_val = self.min, self.max

        # Iterate over provided arguments and validate each
        try:
            iterator = iter(args)
        except TypeError:
            raise TypeError("'args' must be an iterable of values")

        for idx, value in enumerate(iterator):
            if value < min_val or value > max_val:
                raise ValueError(f"Argument at position {idx} ({value}) is outside the allowed range [{min_val}, {max_val}]")
        return args  # return the original arguments if all are valid<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments into control and nested argument dictionaries.

    Controls arguments: control the IR behaviour. These arguments
    will not be included in the spec YAML file.
    Nested arguments: used by the Ansible playbooks and will be
    serialized into the spec YAML file.
    Custom arguments: custom Ansible variables to be used in place of
    normal nested usage.

    :param args: mapping of argument names to values.
    :return: tuple of two dicts (control_args, nested_args)
    """
    # Define a set of keys that are considered control arguments.
    # These are usually top‑level operations that do not affect the
    # configuration data written to the spec file.
    _control_keys = {
        "destroy", "login", "list", "matrix", "action",
        "subcommand", "spec", "specfile", "config",
    }

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if key in _control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Utility to parse a single key-value string.
    def _parse_kv(arg):
        if isinstance(arg, str) and '=' in arg:
            key, _, val = arg.partition('=')
            return key.strip(), val.strip()
        # Support bool flag style: --flag
        if isinstance(arg, str):
            return arg.strip(), True
        # If already a tuple or list of key/value
        if isinstance(arg, (tuple, list)) and len(arg) == 2:
            return str(arg[0]).strip(), str(arg[1]).strip()
        # Fallback: no value
        return str(arg).strip(), None

    # Normalize args into a list of (key, value) pairs
    kv_pairs = []
    if isinstance(args, dict):
        for k, v in args.items():
            kv_pairs.append((k, v))
    elif isinstance(args, (list, tuple)):
        for item in args:
            kv_pairs.append(_parse_kv(item))
    else:
        # If args is a single string or other
        kv_pairs.append(_parse_kv(args))

    for key, value in kv_pairs:
        # Strip leading dashes if any
        key = key.lstrip('-')
        # Determine category
        if key.startswith('control.'):
            ctrl_key = key[len('control.'):]
            control_args[ctrl_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}
        if not isinstance(args, dict):
            # If args is a list of dictionaries, merge them into one dictionary
            merged = {}
            for item in args:
                if isinstance(item, dict):
                    merged.update(item)
            args = merged

        for key, value in args.items():
            # Normalize key: remove any leading dashes or namespace prefixes
            clean_key = key.lstrip('-')
            if clean_key.startswith('control_'):
                # Strip the control_ prefix for the output key
                control_key = clean_key[len('control_') :]
                control_args[control_key] = value
            elif clean_key.startswith('nested_'):
                # Strip the nested_ prefix for the output key
                nested_key = clean_key[len('nested_') :]
                nested_args[nested_key] = value
            else:
                # Treat any key that doesn't match the prefixes as a custom
                # argument that should flow into the nested arguments
                nested_args[clean_key] = value

        return control_args, nested_args<|return|>

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list of dictionaries")
    for ev in extra_vars:
        if not isinstance(ev, dict):
            raise TypeError("each item in extra_vars must be a dict")
        vars_dict.update(ev)
    return vars_dict<|return|>

