    for item in extra_vars:
        if isinstance(item, dict):
            vars_dict.update(item)
        else:
            # Attempt to parse key=value pairs
            if isinstance(item, str):
                try:
                    key, value = item.split("=", 1)
                    vars_dict[key] = value
                except ValueError:
                    # ignore malformed items
