    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")
    if not extra_vars:
        # Nothing to merge; return the original dict unchanged
        return vars_dict
    # Normalize extra_vars to a list of dictionaries
    if isinstance(extra_vars, dict):
        extras = [extra_vars]
    else:
        try:
            extras = list(extra_vars)
        except TypeError:
            raise TypeError(f"extra_vars must be a dict or an iterable of dicts, got {type(extra_vars).__name__}")
    merged = {}
    for d in extras:
        if not isinstance(d, dict):
            raise TypeError(f"Each item in extra_vars must be a dict, got {type(d).__name__}")
        merged.update(d)
    vars_dict.update(merged)
    return vars_dict<|return|>

def merge_extra_vars(vars_dict, extra_vars=None):
