        try:
            if target_type is bool:
                values_dict[key] = _to_bool(val)
            elif target_type in (int, float):
                # Handle comma-separated lists (e.g., "1,2,3")
                if isinstance(val, str) and ',' in val:
                    # Convert each component
                    values_dict[key] = [target_type(v.strip()) for v in val.split(',')]
                else:
                    values_dict[key] = target_type(val)
            elif target_type is list:
                # If string list is comma-separated, split and keep as strings
                if isinstance(val, str) and ',' in val:
                    values_dict[key] = [v.strip() for v in val.split(',')]
                else:
                    values_dict[key] = list(val) if hasattr(val, '__iter__') else [val]
            else:
                # Default conversion: call the type
                values_dict[key] = target_type(val)
        except Exception:
            # If conversion fails, preserve original string
            pass
