def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, val in values_dict.items():
        if isinstance(val, str):
            lower_val = val.lower()
            # Boolean values
            if lower_val in ("true", "false"):
                values_dict[key] = lower_val == "true"
                continue
            # Numeric values
            if val.replace(".", "", 1).isdigit():
                if "." in val:
                    try:
                        values_dict[key] = float(val)
                    except ValueError:
                        pass
                else:
                    try:
                        values_dict[key] = int(val)
                    except ValueError:
                        pass
                continue
            # List values separated by commas
            if "," in val:
                values_dict[key] = [v.strip() for v in val.split(",")]
    # The dictionary is modified in place; nothing is returned.<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:  # pragma: no cover
        yaml = None

    # Detect spec file (plugin.yaml or plugin.json)
    spec_file = None
    for fname in ('plugin.yaml', 'plugin.yml', 'plugin.json'):
        potential = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential):
            spec_file = potential
            break

    if not spec_file:
        return {}

    # Load the spec
    if spec_file.endswith(('.yaml', '.yml')) and yaml:
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec = yaml.safe_load(f) or {}
    else:
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec = json.load(f) or {}

    # Helper to flatten nested dicts
    def _flatten(d, parent_key=''):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)<|return|>

