def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    # yaml may not be available, but will be used if a yaml file is detected
    try:
        import yaml
    except ImportError:
        yaml = None

    # Potential spec file names in priority order
    spec_candidates = ['plugin.json', 'plugin.yaml', 'plugin.yml',
                       'spec.json', 'spec.yaml', 'spec.yml']

    spec_data = None
    for fname in spec_candidates:
        spec_path = os.path.join(plugin_dir, fname)
        if os.path.isfile(spec_path):
            with open(spec_path, 'r', encoding='utf-8') as f:
                if fname.endswith('.json'):
                    spec_data = json.load(f)
                else:
                    if yaml is None:
                        raise RuntimeError(f"YAML support is required to read {fname}")
                    spec_data = yaml.safe_load(f)
            break

    if spec_data is None:
        raise FileNotFoundError(f"No spec file found in {plugin_dir}")

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                for i, elem in enumerate(v):
                    if isinstance(elem, dict):
                        items.update(_flatten(elem, f"{new_key}{sep}{i}", sep=sep))
                    else:
                        items[f"{new_key}{sep}{i}"] = elem
            else:
                items[new_key] = v
        return items

    return _flatten(spec_data)<|return|>

